// Define the schema
pub mod schema {
    table! {
        users (id) {
            id -> Int4,
            email -> Varchar,
            username -> Varchar,
            password_hash -> Varchar,
            is_active -> Bool,
            created_at -> Timestamptz,
            updated_at -> Timestamptz,
        }
    }

    table! {
        posts (id) {
            id -> Int4,
            user_id -> Int4,
            title -> Varchar,
            content -> Text,
            published -> Bool,
            created_at -> Timestamptz,
            updated_at -> Timestamptz,
        }
    }

    table! {
        comments (id) {
            id -> Int4,
            post_id -> Int4,
            user_id -> Int4,
            content -> Text,
            created_at -> Timestamptz,
        }
    }

    joinable!(posts -> users (user_id));
    joinable!(comments -> posts (post_id));
    joinable!(comments -> users (user_id));

    allow_tables_to_appear_in_same_query!(users, posts, comments);
}

