            status: TransactionStatus::Completed,
            timestamp: Utc::now(),
            metadata: None,
        };

        let json = serde_json::to_string_pretty(&transaction).unwrap();
        println!("Serialized transaction:
{}", json);

        let deserialized: Transaction = serde_json::from_str(&json).unwrap();
        assert_eq!(transaction.id, deserialized.id);
        assert_eq!(transaction.status, deserialized.status);
    }

    #[test]
    fn test_api_response() {
        let response = ApiResponse::success(vec!["item1", "item2"]);
        let json = serde_json::to_string_pretty(&response).unwrap();
        println!("Success response:
{}", json);

        let error_response: ApiResponse<()> = ApiResponse::error("NOT_FOUND", "Resource not found");
        let error_json = serde_json::to_string_pretty(&error_response).unwrap();
        println!("Error response:
{}", error_json);
    }
}

use dashmap::{DashMap, DashSet};
use std::sync::Arc;
use std::thread;
use std::time::Duration;
use serde::{Deserialize, Serialize};

// Cache with automatic expiration
#[derive(Clone, Serialize, Deserialize)]
pub struct CacheEntry<T> {
    pub value: T,
    pub expires_at: std::time::Instant,
}

pub struct ExpiringCache<K, V> {
    map: Arc<DashMap<K, CacheEntry<V>>>,
}

impl<K, V> ExpiringCache<K, V>
where
    K: Eq + std::hash::Hash + Clone,
    V: Clone,
{
    pub fn new() -> Self {
        Self {
            map: Arc::new(DashMap::new()),
        }
    }

    pub fn insert(&self, key: K, value: V, ttl: Duration) {
        let entry = CacheEntry {
            value,
            expires_at: std::time::Instant::now() + ttl,
        };
        self.map.insert(key, entry);
    }

    pub fn get(&self, key: &K) -> Option<V> {
        self.map.get(key).and_then(|entry| {
            if entry.expires_at > std::time::Instant::now() {
                Some(entry.value.clone())
            } else {
                drop(entry);
                self.map.remove(key);
                None
            }
        })
    }

    pub fn remove(&self, key: &K) -> Option<V> {
        self.map.remove(key).map(|(_, entry)| entry.value)
    }

    pub fn cleanup_expired(&self) {
        let now = std::time::Instant::now();
        self.map.retain(|_, entry| entry.expires_at > now);
    }

    pub fn len(&self) -> usize {
        self.map.len()
    }
}

// Concurrent session store
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Session {
    pub user_id: String,
    pub created_at: chrono::DateTime<chrono::Utc>,
    pub last_accessed: chrono::DateTime<chrono::Utc>,
    pub data: serde_json::Value,
}

pub struct SessionStore {
    sessions: Arc<DashMap<String, Session>>,
}

impl SessionStore {
    pub fn new() -> Self {
        Self {
            sessions: Arc::new(DashMap::new()),
        }
    }

    pub fn create_session(&self, user_id: String) -> String {
        let session_id = uuid::Uuid::new_v4().to_string();
        let session = Session {
            user_id,
            created_at: chrono::Utc::now(),
            last_accessed: chrono::Utc::now(),
            data: serde_json::json!({}),
        };
        self.sessions.insert(session_id.clone(), session);
        session_id
    }

    pub fn get_session(&self, session_id: &str) -> Option<Session> {
        self.sessions.get_mut(session_id).map(|mut entry| {
            entry.last_accessed = chrono::Utc::now();
            entry.clone()
        })
    }

    pub fn update_session_data(&self, session_id: &str, data: serde_json::Value) -> bool {
        self.sessions.get_mut(session_id).map(|mut session| {
            session.data = data;
            session.last_accessed = chrono::Utc::now();
        }).is_some()
    }

    pub fn delete_session(&self, session_id: &str) -> bool {
        self.sessions.remove(session_id).is_some()
    }

    pub fn cleanup_inactive(&self, max_age: Duration) {
        let cutoff = chrono::Utc::now() - chrono::Duration::from_std(max_age).unwrap();
        self.sessions.retain(|_, session| session.last_accessed > cutoff);
    }

    pub fn active_sessions(&self) -> usize {
        self.sessions.len()
    }
}

// Concurrent metrics collector
pub struct MetricsCollector {
    counters: Arc<DashMap<String, u64>>,
    gauges: Arc<DashMap<String, f64>>,
}

impl MetricsCollector {
    pub fn new() -> Self {
        Self {
            counters: Arc::new(DashMap::new()),
            gauges: Arc::new(DashMap::new()),
        }
    }

    pub fn increment_counter(&self, name: &str, value: u64) {
        self.counters
            .entry(name.to_string())
            .and_modify(|v| *v += value)
            .or_insert(value);
    }

    pub fn set_gauge(&self, name: &str, value: f64) {
        self.gauges.insert(name.to_string(), value);
    }

    pub fn get_counter(&self, name: &str) -> Option<u64> {
        self.counters.get(name).map(|v| *v)
    }

    pub fn get_gauge(&self, name: &str) -> Option<f64> {
        self.gauges.get(name).map(|v| *v)
    }

    pub fn snapshot(&self) -> (Vec<(String, u64)>, Vec<(String, f64)>) {
        let counters: Vec<_> = self.counters
            .iter()
            .map(|entry| (entry.key().clone(), *entry.value()))
            .collect();

        let gauges: Vec<_> = self.gauges
            .iter()
            .map(|entry| (entry.key().clone(), *entry.value()))
            .collect();

        (counters, gauges)
    }

    pub fn reset(&self) {
        self.counters.clear();
        self.gauges.clear();
    }
}

// Distributed rate limiter
pub struct RateLimiter {
    requests: Arc<DashMap<String, Vec<std::time::Instant>>>,
    max_requests: usize,
    window: Duration,
}

impl RateLimiter {
    pub fn new(max_requests: usize, window: Duration) -> Self {
        Self {
            requests: Arc::new(DashMap::new()),
            max_requests,
            window,
        }
    }

    pub fn check_rate_limit(&self, key: &str) -> bool {
        let now = std::time::Instant::now();
        let cutoff = now - self.window;

        let mut entry = self.requests.entry(key.to_string()).or_insert_with(Vec::new);

        // Remove old requests
        entry.retain(|&timestamp| timestamp > cutoff);

        if entry.len() < self.max_requests {
            entry.push(now);
            true
        } else {
            false
        }
    }

    pub fn cleanup(&self) {
        let cutoff = std::time::Instant::now() - self.window;
        self.requests.retain(|_, timestamps| {
            !timestamps.is_empty() && timestamps.last().map_or(false, |&t| t > cutoff)
        });
    }
}

// Concurrent set operations
pub struct UniqueVisitors {
    visitors: Arc<DashSet<String>>,
}

impl UniqueVisitors {
    pub fn new() -> Self {
        Self {
            visitors: Arc::new(DashSet::new()),
        }
    }

    pub fn visit(&self, visitor_id: String) -> bool {
        self.visitors.insert(visitor_id)
    }

    pub fn has_visited(&self, visitor_id: &str) -> bool {
        self.visitors.contains(visitor_id)
    }

    pub fn count(&self) -> usize {
        self.visitors.len()
    }

    pub fn clear(&self) {
        self.visitors.clear();
    }
}

// Example usage
fn main() {
    // Expiring cache
    let cache = Arc::new(ExpiringCache::new());
    cache.insert("key1", "value1", Duration::from_secs(2));

    println!("Value: {:?}", cache.get(&"key1"));
    thread::sleep(Duration::from_secs(3));
    println!("Value after expiry: {:?}", cache.get(&"key1"));

    // Session store
    let store = Arc::new(SessionStore::new());
    let session_id = store.create_session("user123".to_string());
    println!("Created session: {}", session_id);

    if let Some(session) = store.get_session(&session_id) {
        println!("Session user: {}", session.user_id);
    }

    // Metrics collector
    let metrics = Arc::new(MetricsCollector::new());

    let handles: Vec<_> = (0..10)
        .map(|i| {
            let metrics = metrics.clone();
            thread::spawn(move || {
                for _ in 0..100 {
                    metrics.increment_counter("requests", 1);
                    metrics.set_gauge(&format!("worker_{}", i), i as f64 * 1.5);
                }
            })
        })
        .collect();

    for handle in handles {
        handle.join().unwrap();
    }

    let (counters, gauges) = metrics.snapshot();
    println!("Total requests: {:?}", counters);
    println!("Number of gauges: {}", gauges.len());

    // Rate limiter
    let limiter = Arc::new(RateLimiter::new(5, Duration::from_secs(1)));

    for i in 0..10 {
        let allowed = limiter.check_rate_limit("user123");
        println!("Request {}: {}", i, if allowed { "allowed" } else { "blocked" });
    }

    // Unique visitors
    let visitors = Arc::new(UniqueVisitors::new());

    visitors.visit("visitor1".to_string());
    visitors.visit("visitor2".to_string());
    visitors.visit("visitor1".to_string()); // Duplicate

    println!("Unique visitors: {}", visitors.count());
}

use chrono::{DateTime, Utc, Local, NaiveDate, NaiveTime, NaiveDateTime, Duration};
use chrono::{Datelike, Timelike, Weekday};
use chrono_tz::{Tz, America, Europe, Asia};
use serde::{Deserialize, Serialize};

#[derive(Debug, Serialize, Deserialize)]
pub struct TimeRange {
    pub start: DateTime<Utc>,
    pub end: DateTime<Utc>,
}

impl TimeRange {
    pub fn new(start: DateTime<Utc>, end: DateTime<Utc>) -> Self {
        Self { start, end }
    }

    pub fn duration(&self) -> Duration {
        self.end - self.start
    }

    pub fn contains(&self, dt: &DateTime<Utc>) -> bool {
        dt >= &self.start && dt <= &self.end
    }

    pub fn overlaps(&self, other: &TimeRange) -> bool {
        self.start < other.end && other.start < self.end
    }
}

// Working with different timezones
pub fn timezone_conversions() {
    let utc_now = Utc::now();
    println!("UTC: {}", utc_now.to_rfc3339());

    // Convert to different timezones
    let ny_time = utc_now.with_timezone(&America::New_York);
    println!("New York: {}", ny_time.format("%Y-%m-%d %H:%M:%S %Z"));

    let london_time = utc_now.with_timezone(&Europe::London);
    println!("London: {}", london_time.format("%Y-%m-%d %H:%M:%S %Z"));

    let tokyo_time = utc_now.with_timezone(&Asia::Tokyo);
    println!("Tokyo: {}", tokyo_time.format("%Y-%m-%d %H:%M:%S %Z"));
}

// Date arithmetic and business logic
pub fn calculate_business_days(start: NaiveDate, end: NaiveDate) -> i64 {
    let mut current = start;
    let mut business_days = 0;

    while current <= end {
        let weekday = current.weekday();
        if weekday != Weekday::Sat && weekday != Weekday::Sun {
            business_days += 1;
        }
        current = current.succ_opt().unwrap();
    }

    business_days
}

pub fn add_business_days(start: NaiveDate, days: i64) -> NaiveDate {
    let mut current = start;
    let mut remaining = days;

    while remaining > 0 {
        current = current.succ_opt().unwrap();
        let weekday = current.weekday();
        if weekday != Weekday::Sat && weekday != Weekday::Sun {
            remaining -= 1;
        }
    }

    current
}

// Parsing and formatting
pub fn parse_various_formats(input: &str) -> Result<DateTime<Utc>, chrono::ParseError> {
    // Try multiple formats
    let formats = vec![
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%dT%H:%M:%S",
        "%Y-%m-%d %H:%M:%S%.f",
        "%d/%m/%Y %H:%M",
        "%m/%d/%Y %I:%M %p",
    ];

    for format in formats {
        if let Ok(naive) = NaiveDateTime::parse_from_str(input, format) {
            return Ok(DateTime::from_naive_utc_and_offset(naive, Utc));
        }
    }

    // Try RFC3339
    input.parse::<DateTime<Utc>>()
}

pub fn format_human_readable(dt: DateTime<Utc>) -> String {
    let now = Utc::now();
    let diff = now - dt;

    if diff < Duration::minutes(1) {
        "just now".to_string()
    } else if diff < Duration::hours(1) {
        format!("{} minutes ago", diff.num_minutes())
    } else if diff < Duration::days(1) {
        format!("{} hours ago", diff.num_hours())
    } else if diff < Duration::days(7) {
        format!("{} days ago", diff.num_days())
    } else if diff < Duration::days(30) {
        format!("{} weeks ago", diff.num_weeks())
    } else {
        dt.format("%B %d, %Y").to_string()
    }
}

// Recurring events
#[derive(Debug)]
pub enum RecurrenceRule {
    Daily,
    Weekly { day: Weekday },
    Monthly { day_of_month: u32 },
    Yearly { month: u32, day: u32 },
}

pub fn generate_occurrences(
    start: DateTime<Utc>,
    rule: RecurrenceRule,
    count: usize,
) -> Vec<DateTime<Utc>> {
    let mut occurrences = Vec::new();
    let mut current = start;

    for _ in 0..count {
        occurrences.push(current);

        current = match rule {
            RecurrenceRule::Daily => current + Duration::days(1),
            RecurrenceRule::Weekly { day } => {
                let mut next = current + Duration::days(1);
                while next.weekday() != day {
                    next = next + Duration::days(1);
                }
                next
            }
            RecurrenceRule::Monthly { day_of_month } => {
                let next_month = if current.month() == 12 {
                    NaiveDate::from_ymd_opt(current.year() + 1, 1, day_of_month)
                } else {
                    NaiveDate::from_ymd_opt(current.year(), current.month() + 1, day_of_month)
                };

                if let Some(date) = next_month {
                    DateTime::from_naive_utc_and_offset(
                        date.and_time(current.time()),
                        Utc,
                    )
                } else {
                    current
                }
            }
            RecurrenceRule::Yearly { month, day } => {
                if let Some(date) = NaiveDate::from_ymd_opt(current.year() + 1, month, day) {
                    DateTime::from_naive_utc_and_offset(
                        date.and_time(current.time()),
                        Utc,
                    )
                } else {
                    current
                }
            }
        };
    }

    occurrences
}

// Working hours calculation
pub struct WorkingHours {
    pub start: NaiveTime,
    pub end: NaiveTime,
}

impl WorkingHours {
    pub fn standard() -> Self {
        Self {
            start: NaiveTime::from_hms_opt(9, 0, 0).unwrap(),
            end: NaiveTime::from_hms_opt(17, 0, 0).unwrap(),
        }
    }

    pub fn is_within_hours(&self, dt: DateTime<Utc>) -> bool {
        let time = dt.time();
        time >= self.start && time <= self.end
    }

    pub fn next_available_time(&self, dt: DateTime<Utc>) -> DateTime<Utc> {
        let mut current = dt;

        loop {
            // Skip weekends
            let weekday = current.weekday();
            if weekday == Weekday::Sat || weekday == Weekday::Sun {
                current = current + Duration::days(1);
                current = current
                    .date_naive()
                    .and_time(self.start)
                    .and_utc();
                continue;
            }

            // Check if within working hours
            if current.time() < self.start {
                return current.date_naive().and_time(self.start).and_utc();
            } else if current.time() > self.end {
                current = current + Duration::days(1);
                current = current.date_naive().and_time(self.start).and_utc();
            } else {
                return current;
            }
        }
    }
}

// Example usage
fn main() {
    // Timezone conversions
    timezone_conversions();

    // Business days
    let start_date = NaiveDate::from_ymd_opt(2025, 1, 1).unwrap();
    let end_date = NaiveDate::from_ymd_opt(2025, 1, 31).unwrap();
    let business_days = calculate_business_days(start_date, end_date);
    println!("Business days in January 2025: {}", business_days);

    // Add 10 business days
    let future_date = add_business_days(start_date, 10);
    println!("10 business days from Jan 1: {}", future_date);

    // Human-readable formatting
    let past = Utc::now() - Duration::hours(5);
    println!("Relative time: {}", format_human_readable(past));

    // Recurring events
    let start = Utc::now();
    let weekly_meetings = generate_occurrences(
        start,
        RecurrenceRule::Weekly { day: Weekday::Mon },
        4,
    );
    println!("Next 4 Monday meetings:");
    for meeting in weekly_meetings {
        println!("  {}", meeting.format("%Y-%m-%d %H:%M"));
    }

    // Working hours
    let hours = WorkingHours::standard();
    let now = Utc::now();
    if hours.is_within_hours(now) {
        println!("Currently within working hours");
    } else {
        let next = hours.next_available_time(now);
        println!("Next available time: {}", next.format("%Y-%m-%d %H:%M"));
    }
}

use tokio_tungstenite::{
    connect_async, tungstenite::protocol::Message, MaybeTlsStream, WebSocketStream,
};
use tokio::net::{TcpListener, TcpStream};
use tokio_tungstenite::accept_async;
use futures_util::{StreamExt, SinkExt, stream::{SplitSink, SplitStream}};
use serde::{Deserialize, Serialize};
use std::sync::Arc;
use tokio::sync::{mpsc, RwLock};
use std::collections::HashMap;
use std::time::Duration;

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum WsMessage {
    Ping { timestamp: i64 },
    Pong { timestamp: i64 },
    Subscribe { channels: Vec<String> },
    Unsubscribe { channels: Vec<String> },
    Message { channel: String, data: String },
    Error { code: String, message: String },
    Auth { token: String },
    AuthSuccess { user_id: String },
}

impl WsMessage {
    pub fn to_text(&self) -> Result<String, serde_json::Error> {
        serde_json::to_string(self)
    }

    pub fn from_text(text: &str) -> Result<Self, serde_json::Error> {
        serde_json::from_str(text)
    }
}

// ============================================
// WebSocket Client with Auto-Reconnect
// ============================================

pub struct WsClient {
    url: String,
    sender: mpsc::UnboundedSender<WsMessage>,
    receiver: Arc<RwLock<mpsc::UnboundedReceiver<WsMessage>>>,
}

impl WsClient {
    pub async fn connect(url: impl Into<String>) -> anyhow::Result<Self> {
        let url = url.into();
        let (tx, rx) = mpsc::unbounded_channel();
        let (internal_tx, internal_rx) = mpsc::unbounded_channel();

        let client = Self {
            url: url.clone(),
            sender: internal_tx,
            receiver: Arc::new(RwLock::new(rx)),
        };

        // Spawn connection handler
        tokio::spawn(Self::connection_handler(
            url.clone(),
            tx,
            internal_rx,
        ));

        Ok(client)
    }

    async fn connection_handler(
        url: String,
        outbound: mpsc::UnboundedSender<WsMessage>,
        mut inbound: mpsc::UnboundedReceiver<WsMessage>,
    ) {
        let mut retry_count = 0;
        const MAX_RETRIES: u32 = 5;
        const RETRY_DELAY: Duration = Duration::from_secs(2);

        loop {
            match Self::maintain_connection(&url, &outbound, &mut inbound).await {
                Ok(_) => {
                    tracing::info!("WebSocket connection closed normally");
                    break;
                }
                Err(e) => {
                    retry_count += 1;
                    tracing::error!(
                        "WebSocket error (attempt {}/{}): {}",
                        retry_count,
                        MAX_RETRIES,
                        e
                    );

                    if retry_count >= MAX_RETRIES {
                        tracing::error!("Max retries reached, giving up");
                        let _ = outbound.send(WsMessage::Error {
                            code: "max_retries".to_string(),
                            message: "Failed to connect after maximum retries".to_string(),
                        });
                        break;
                    }

                    tokio::time::sleep(RETRY_DELAY).await;
                }
            }
        }
    }

    async fn maintain_connection(
        url: &str,
        outbound: &mpsc::UnboundedSender<WsMessage>,
        inbound: &mut mpsc::UnboundedReceiver<WsMessage>,
    ) -> anyhow::Result<()> {
        tracing::info!("Connecting to {}", url);
        let (ws_stream, _) = connect_async(url).await?;
        tracing::info!("WebSocket connected");

        let (mut write, mut read) = ws_stream.split();

        // Spawn heartbeat task
        let heartbeat_tx = outbound.clone();
        let heartbeat = tokio::spawn(async move {
            let mut interval = tokio::time::interval(Duration::from_secs(30));
            loop {
                interval.tick().await;
                let msg = WsMessage::Ping {
                    timestamp: chrono::Utc::now().timestamp(),
                };
                if heartbeat_tx.send(msg).is_err() {
                    break;
                }
            }
        });

        loop {
            tokio::select! {
                // Handle incoming messages from WebSocket
                msg = read.next() => {
                    match msg {
                        Some(Ok(Message::Text(text))) => {
                            if let Ok(ws_msg) = WsMessage::from_text(&text) {
                                if outbound.send(ws_msg).is_err() {
                                    break;
                                }
                            }
                        }
                        Some(Ok(Message::Close(_))) => {
                            tracing::info!("Received close frame");
                            break;
                        }
                        Some(Err(e)) => {
                            tracing::error!("WebSocket error: {}", e);
                            break;
                        }
                        None => break,
                        _ => {}
                    }
                }

                // Handle outgoing messages
                msg = inbound.recv() => {
                    match msg {
                        Some(ws_msg) => {
                            if let Ok(text) = ws_msg.to_text() {
                                write.send(Message::Text(text)).await?;
                            }
                        }
                        None => break,
                    }
                }
            }
        }

        heartbeat.abort();
        Ok(())
    }

    pub fn send(&self, msg: WsMessage) -> anyhow::Result<()> {
        self.sender
            .send(msg)
            .map_err(|e| anyhow::anyhow!("Failed to send message: {}", e))
    }

    pub async fn recv(&self) -> Option<WsMessage> {
        self.receiver.write().await.recv().await
    }
}

// ============================================
// WebSocket Server with Channel Management
// ============================================

type ClientId = String;
type ChannelName = String;

#[derive(Clone)]
struct Client {
    id: ClientId,
    sender: mpsc::UnboundedSender<WsMessage>,
    subscriptions: Arc<RwLock<Vec<ChannelName>>>,
}

pub struct WsServer {
    clients: Arc<RwLock<HashMap<ClientId, Client>>>,
    channels: Arc<RwLock<HashMap<ChannelName, Vec<ClientId>>>>,
}

impl WsServer {
    pub fn new() -> Self {
        Self {
            clients: Arc::new(RwLock::new(HashMap::new())),
            channels: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    pub async fn start(self: Arc<Self>, addr: &str) -> anyhow::Result<()> {
        let listener = TcpListener::bind(addr).await?;
        tracing::info!("WebSocket server listening on {}", addr);

        while let Ok((stream, peer)) = listener.accept().await {
            tracing::info!("New connection from {}", peer);
            let server = self.clone();
            tokio::spawn(async move {
                if let Err(e) = server.handle_connection(stream).await {
                    tracing::error!("Error handling connection: {}", e);
                }
            });
        }

        Ok(())
    }

    async fn handle_connection(&self, stream: TcpStream) -> anyhow::Result<()> {
        let ws_stream = accept_async(stream).await?;
        let (write, read) = ws_stream.split();

        let client_id = uuid::Uuid::new_v4().to_string();
        let (tx, rx) = mpsc::unbounded_channel();

        let client = Client {
            id: client_id.clone(),
            sender: tx,
            subscriptions: Arc::new(RwLock::new(Vec::new())),
        };

        self.clients.write().await.insert(client_id.clone(), client.clone());

        // Spawn writer task
        tokio::spawn(Self::write_task(write, rx));

        // Handle incoming messages
        self.handle_messages(client_id.clone(), read, client).await?;

        // Cleanup
        self.remove_client(&client_id).await;

        Ok(())
    }

    async fn write_task(
        mut write: SplitSink<WebSocketStream<TcpStream>, Message>,
        mut rx: mpsc::UnboundedReceiver<WsMessage>,
    ) {
        while let Some(msg) = rx.recv().await {
            if let Ok(text) = msg.to_text() {
                if write.send(Message::Text(text)).await.is_err() {
                    break;
                }
            }
        }
    }

    async fn handle_messages(
        &self,
        client_id: String,
        mut read: SplitStream<WebSocketStream<TcpStream>>,
        client: Client,
    ) -> anyhow::Result<()> {
        while let Some(msg) = read.next().await {
            match msg? {
                Message::Text(text) => {
                    if let Ok(ws_msg) = WsMessage::from_text(&text) {
                        self.handle_message(client_id.clone(), ws_msg, &client).await;
                    }
                }
                Message::Close(_) => break,
                _ => {}
            }
        }
        Ok(())
    }

    async fn handle_message(&self, client_id: String, msg: WsMessage, client: &Client) {
        match msg {
            WsMessage::Ping { timestamp } => {
                let _ = client.sender.send(WsMessage::Pong { timestamp });
            }
            WsMessage::Subscribe { channels } => {
                for channel in channels {
                    self.subscribe_client(&client_id, &channel).await;
                    client.subscriptions.write().await.push(channel);
                }
            }
            WsMessage::Unsubscribe { channels } => {
                for channel in channels {
                    self.unsubscribe_client(&client_id, &channel).await;
                    client
                        .subscriptions
                        .write()
                        .await
                        .retain(|c| c != &channel);
                }
            }
            WsMessage::Message { channel, data } => {
                self.broadcast_to_channel(&channel, WsMessage::Message { channel, data })
                    .await;
            }
            _ => {}
        }
    }

    async fn subscribe_client(&self, client_id: &str, channel: &str) {
        let mut channels = self.channels.write().await;
        channels
            .entry(channel.to_string())
            .or_insert_with(Vec::new)
            .push(client_id.to_string());

        tracing::info!("Client {} subscribed to channel {}", client_id, channel);
    }

    async fn unsubscribe_client(&self, client_id: &str, channel: &str) {
        let mut channels = self.channels.write().await;
        if let Some(subscribers) = channels.get_mut(channel) {
            subscribers.retain(|id| id != client_id);
        }

        tracing::info!("Client {} unsubscribed from channel {}", client_id, channel);
    }

    async fn broadcast_to_channel(&self, channel: &str, msg: WsMessage) {
        let channels = self.channels.read().await;
        if let Some(subscribers) = channels.get(channel) {
            let clients = self.clients.read().await;
            for client_id in subscribers {
                if let Some(client) = clients.get(client_id) {
                    let _ = client.sender.send(msg.clone());
                }
            }
        }
    }

    async fn remove_client(&self, client_id: &str) {
        // Remove from all channels
        let mut channels = self.channels.write().await;
        for subscribers in channels.values_mut() {
            subscribers.retain(|id| id != client_id);
        }

        // Remove client
        self.clients.write().await.remove(client_id);
        tracing::info!("Client {} disconnected", client_id);
    }
}

// Example usage
#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt::init();

    // Start server
    let server = Arc::new(WsServer::new());
    let server_clone = server.clone();
    tokio::spawn(async move {
        if let Err(e) = server_clone.start("127.0.0.1:9001").await {
            tracing::error!("Server error: {}", e);
        }
    });

    // Give server time to start
    tokio::time::sleep(Duration::from_millis(100)).await;

    // Connect client
    let client = WsClient::connect("ws://127.0.0.1:9001").await?;

    // Subscribe to channels
    client.send(WsMessage::Subscribe {
        channels: vec!["chat".to_string(), "notifications".to_string()],
    })?;

    // Send a message
    client.send(WsMessage::Message {
        channel: "chat".to_string(),
        data: "Hello, WebSocket!".to_string(),
    })?;

    // Receive messages
    tokio::spawn(async move {
        while let Some(msg) = client.recv().await {
            tracing::info!("Received: {:?}", msg);
        }
    });

    tokio::time::sleep(Duration::from_secs(60)).await;

    Ok(())
}

