    println!("API Key: {}", CONFIG.api_key);
    println!("Max connections: {}", CONFIG.max_connections);

    // Use database pool
    {
        let mut pool = DB_POOL.lock().unwrap();
        if let Some(conn) = pool.get_connection() {
            println!("Got connection: {}", conn);
            pool.release_connection(conn);
        }
    }

    // Use registry
