use tokio::{
    sync::{mpsc, Semaphore},
    time::{sleep, Duration, interval},
    select,
    signal,
};
use std::sync::Arc;
use thiserror::Error;
use tracing::{error, info, warn};

#[derive(Debug, Error)]
pub enum ProcessError {
    #[error("Task failed: {0}")]
    TaskFailed(String),

    #[error("Rate limit exceeded")]
    RateLimitExceeded,

    #[error("Timeout")]
    Timeout,
}

#[derive(Debug, Clone)]
pub struct Task {
    pub id: String,
    pub data: String,
    pub priority: u8,
}

#[derive(Debug, Clone)]
pub struct TaskResult {
    pub task_id: String,
    pub success: bool,
    pub error: Option<String>,
    pub duration: Duration,
}

pub struct TaskProcessor {
    max_concurrent_tasks: usize,
    max_retries: u32,
    retry_delay: Duration,
    rate_limit_per_second: usize,
    shutdown_tx: mpsc::Sender<()>,
    shutdown_rx: mpsc::Receiver<()>,
}

impl TaskProcessor {
    pub fn new(
        max_concurrent_tasks: usize,
        max_retries: u32,
        retry_delay: Duration,
        rate_limit_per_second: usize,
    ) -> Self {
        let (shutdown_tx, shutdown_rx) = mpsc::channel(1);

        Self {
            max_concurrent_tasks,
            max_retries,
            retry_delay,
            rate_limit_per_second,
            shutdown_tx,
            shutdown_rx,
        }
    }

    pub async fn process_tasks(
        mut self,
        mut task_rx: mpsc::Receiver<Task>,
        result_tx: mpsc::Sender<TaskResult>,
    ) -> anyhow::Result<()> {
        info!("Task processor started with {} concurrent tasks", self.max_concurrent_tasks);

        // Semaphore for controlling concurrent tasks
        let semaphore = Arc::new(Semaphore::new(self.max_concurrent_tasks));

        // Rate limiter using a token bucket approach
        let rate_limiter = Arc::new(Semaphore::new(self.rate_limit_per_second));
        let rate_limit_permits = self.rate_limit_per_second;

        // Spawn rate limiter refill task
        let rate_limiter_clone = rate_limiter.clone();
        tokio::spawn(async move {
            let mut interval = interval(Duration::from_secs(1));
            loop {
                interval.tick().await;
                // Refill permits up to the limit
                let current_permits = rate_limiter_clone.available_permits();
                if current_permits < rate_limit_permits {
                    rate_limiter_clone.add_permits(rate_limit_permits - current_permits);
                }
            }
        });

        // Main processing loop
        loop {
            select! {
                // Receive new tasks
                Some(task) = task_rx.recv() => {
                    let semaphore = semaphore.clone();
                    let rate_limiter = rate_limiter.clone();
                    let result_tx = result_tx.clone();
                    let max_retries = self.max_retries;
                    let retry_delay = self.retry_delay;

                    tokio::spawn(async move {
                        // Wait for rate limit permit
                        let _rate_permit = match rate_limiter.acquire().await {
                            Ok(p) => p,
                            Err(_) => {
                                error!("Rate limiter closed");
                                return;
                            }
                        };

                        // Wait for concurrency permit
                        let _permit = match semaphore.acquire().await {
                            Ok(p) => p,
                            Err(_) => {
                                error!("Semaphore closed");
                                return;
                            }
                        };

                        info!("Processing task: {}", task.id);
                        let start = tokio::time::Instant::now();

                        // Execute task with retries
                        let result = Self::execute_with_retries(
                            task.clone(),
                            max_retries,
                            retry_delay,
                        ).await;

                        let duration = start.elapsed();

                        let task_result = match result {
                            Ok(_) => {
                                info!("Task {} completed successfully in {:?}", task.id, duration);
                                TaskResult {
                                    task_id: task.id,
                                    success: true,
                                    error: None,
                                    duration,
                                }
                            }
                            Err(e) => {
                                error!("Task {} failed after retries: {}", task.id, e);
                                TaskResult {
                                    task_id: task.id,
                                    success: false,
                                    error: Some(e.to_string()),
                                    duration,
                                }
                            }
                        };

                        let _ = result_tx.send(task_result).await;
                    });
                }

                // Handle shutdown signal
                _ = self.shutdown_rx.recv() => {
                    info!("Shutdown signal received, draining remaining tasks...");

                    // Wait for all tasks to complete
                    while task_rx.recv().await.is_some() {
                        // Process remaining tasks
                    }

                    info!("All tasks completed, shutting down");
                    break;
                }
            }
        }

        Ok(())
    }

    async fn execute_with_retries(
        task: Task,
        max_retries: u32,
        retry_delay: Duration,
    ) -> Result<(), ProcessError> {
        let mut attempts = 0;

        loop {
            match Self::execute_task(&task).await {
                Ok(_) => return Ok(()),
                Err(e) => {
                    attempts += 1;

                    if attempts > max_retries {
                        return Err(e);
                    }

                    warn!(
                        "Task {} failed (attempt {}/{}): {}. Retrying in {:?}...",
                        task.id, attempts, max_retries, e, retry_delay
                    );

                    sleep(retry_delay).await;
                }
            }
        }
    }

    async fn execute_task(task: &Task) -> Result<(), ProcessError> {
        // Simulate task processing with potential failure
        sleep(Duration::from_millis(100)).await;

        // Simulate random failures for demonstration
        use rand::Rng;
        let mut rng = rand::thread_rng();
        if rng.gen_bool(0.2) {  // 20% chance of failure
            return Err(ProcessError::TaskFailed("Random failure".to_string()));
        }

        // Process the task
        info!("Task {} processing data: {}", task.id, task.data);

        Ok(())
    }

    pub fn shutdown_handle(&self) -> mpsc::Sender<()> {
        self.shutdown_tx.clone()
    }
}

// Example usage
pub async fn run_task_processing_system() -> anyhow::Result<()> {
    // Initialize tracing
    tracing_subscriber::fmt()
        .with_max_level(tracing::Level::INFO)
        .init();

    // Create channels
    let (task_tx, task_rx) = mpsc::channel::<Task>(100);
    let (result_tx, mut result_rx) = mpsc::channel::<TaskResult>(100);

    // Create processor
    let processor = TaskProcessor::new(
        5,  // max concurrent tasks
        3,  // max retries
        Duration::from_secs(1),  // retry delay
        10, // rate limit per second
    );

    let shutdown_handle = processor.shutdown_handle();

    // Spawn processor task
    let processor_handle = tokio::spawn(async move {
        processor.process_tasks(task_rx, result_tx).await
    });

    // Spawn result collector
    let result_collector = tokio::spawn(async move {
        let mut successful = 0;
        let mut failed = 0;

        while let Some(result) = result_rx.recv().await {
            if result.success {
                successful += 1;
            } else {
                failed += 1;
            }

            info!("Stats - Successful: {}, Failed: {}", successful, failed);
        }

        info!("Final stats - Successful: {}, Failed: {}", successful, failed);
    });

    // Spawn task generator
    let task_generator = tokio::spawn(async move {
        for i in 0..20 {
            let task = Task {
                id: format!("task-{}", i),
                data: format!("data-{}", i),
                priority: (i % 3) as u8,
            };

            if task_tx.send(task).await.is_err() {
                error!("Failed to send task");
                break;
            }

            sleep(Duration::from_millis(100)).await;
        }

        info!("All tasks submitted");
    });

    // Wait for Ctrl+C
    signal::ctrl_c().await?;
    info!("Received shutdown signal");

    // Trigger graceful shutdown
    let _ = shutdown_handle.send(()).await;

    // Wait for all tasks to complete
    task_generator.await?;
    processor_handle.await??;
    result_collector.await?;

    info!("System shutdown complete");
    Ok(())
}

use tokio::{select, time::{sleep, Duration, timeout, interval}, sync::{mpsc, oneshot}};
use tokio::task::JoinHandle;
use futures::future::{join, join_all, try_join, try_join_all};
use std::sync::Arc;
use tokio::sync::RwLock;

#[derive(Debug, Clone)]
pub struct Task {
    pub id: String,
    pub duration_ms: u64,
}

#[derive(Debug)]
pub struct TaskResult {
    pub task_id: String,
    pub success: bool,
    pub elapsed_ms: u128,
}

// Pattern 1: Racing multiple operations with select!
pub async fn race_operations() -> String {
    let operation1 = async {
        sleep(Duration::from_millis(100)).await;
        "Operation 1 completed"
    };

    let operation2 = async {
        sleep(Duration::from_millis(150)).await;
        "Operation 2 completed"
    };

    let operation3 = async {
        sleep(Duration::from_millis(50)).await;
        "Operation 3 completed"
    };

    select! {
        result = operation1 => result,
        result = operation2 => result,
        result = operation3 => result,
    }.to_string()
}

// Pattern 2: Processing with timeout and fallback
pub async fn operation_with_timeout_and_fallback(
    primary_task: Task,
    timeout_ms: u64,
) -> Result<TaskResult, String> {
    let start = std::time::Instant::now();

    let primary = async {
        sleep(Duration::from_millis(primary_task.duration_ms)).await;
        TaskResult {
            task_id: primary_task.id.clone(),
            success: true,
            elapsed_ms: start.elapsed().as_millis(),
        }
    };

    let fallback = async {
        sleep(Duration::from_millis(timeout_ms + 100)).await;
        TaskResult {
            task_id: "fallback".to_string(),
            success: false,
            elapsed_ms: start.elapsed().as_millis(),
        }
    };

    select! {
        result = primary => Ok(result),
        _ = sleep(Duration::from_millis(timeout_ms)) => {
            tracing::warn!("Primary task timed out, executing fallback");
            Ok(fallback.await)
        }
    }
}

// Pattern 3: Graceful shutdown with cancellation
pub struct Worker {
    shutdown_tx: Option<oneshot::Sender<()>>,
    handle: Option<JoinHandle<()>>,
}

impl Worker {
    pub fn new(interval_ms: u64) -> Self {
        let (shutdown_tx, mut shutdown_rx) = oneshot::channel();

        let handle = tokio::spawn(async move {
            let mut ticker = interval(Duration::from_millis(interval_ms));
            let mut count = 0;

            loop {
                select! {
                    _ = ticker.tick() => {
                        count += 1;
                        tracing::info!("Worker tick #{}", count);
                    }
                    _ = &mut shutdown_rx => {
                        tracing::info!("Worker received shutdown signal");
                        break;
                    }
                }
            }

            tracing::info!("Worker shutting down gracefully");
        });

        Self {
            shutdown_tx: Some(shutdown_tx),
            handle: Some(handle),
        }
    }

    pub async fn shutdown(mut self) {
        if let Some(tx) = self.shutdown_tx.take() {
            let _ = tx.send(());
        }
        if let Some(handle) = self.handle.take() {
            let _ = handle.await;
        }
    }
}

// Pattern 4: Concurrent task processing with join!
pub async fn process_tasks_concurrently(tasks: Vec<Task>) -> Vec<TaskResult> {
    let futures: Vec<_> = tasks
        .into_iter()
        .map(|task| async move {
            let start = std::time::Instant::now();
            sleep(Duration::from_millis(task.duration_ms)).await;
            TaskResult {
                task_id: task.id,
                success: true,
                elapsed_ms: start.elapsed().as_millis(),
            }
        })
        .collect();

    join_all(futures).await
}

// Pattern 5: Try join with error handling
pub async fn fetch_multiple_resources() -> Result<(String, String, String), String> {
    let fetch1 = async {
        sleep(Duration::from_millis(100)).await;
        Ok::<_, String>("Resource 1".to_string())
    };

    let fetch2 = async {
        sleep(Duration::from_millis(150)).await;
        Ok::<_, String>("Resource 2".to_string())
    };

    let fetch3 = async {
        sleep(Duration::from_millis(50)).await;
        Ok::<_, String>("Resource 3".to_string())
    };

    try_join!(fetch1, fetch2, fetch3)
}

// Pattern 6: Channel-based work distribution
pub struct WorkerPool {
    workers: Vec<JoinHandle<()>>,
    task_tx: mpsc::Sender<Task>,
}

impl WorkerPool {
    pub fn new(num_workers: usize) -> (Self, mpsc::Receiver<TaskResult>) {
        let (task_tx, task_rx) = mpsc::channel::<Task>(100);
        let (result_tx, result_rx) = mpsc::channel::<TaskResult>(100);
        let task_rx = Arc::new(tokio::sync::Mutex::new(task_rx));

        let mut workers = Vec::new();

        for worker_id in 0..num_workers {
            let task_rx = task_rx.clone();
            let result_tx = result_tx.clone();

            let handle = tokio::spawn(async move {
                loop {
                    let task = {
                        let mut rx = task_rx.lock().await;
                        rx.recv().await
                    };

                    match task {
                        Some(task) => {
                            let start = std::time::Instant::now();
                            sleep(Duration::from_millis(task.duration_ms)).await;

                            let result = TaskResult {
                                task_id: task.id,
                                success: true,
                                elapsed_ms: start.elapsed().as_millis(),
                            };

                            tracing::info!("Worker {} completed task", worker_id);

                            if result_tx.send(result).await.is_err() {
                                break;
                            }
                        }
                        None => break,
                    }
                }
            });

            workers.push(handle);
        }

        (Self { workers, task_tx }, result_rx)
    }

    pub async fn submit(&self, task: Task) -> Result<(), String> {
        self.task_tx
            .send(task)
            .await
            .map_err(|e| format!("Failed to submit task: {}", e))
    }

    pub async fn shutdown(self) {
        drop(self.task_tx);
        for handle in self.workers {
            let _ = handle.await;
        }
    }
}

// Pattern 7: Adaptive timeout based on system load
pub struct AdaptiveTimeout {
    base_timeout_ms: u64,
    current_timeout_ms: Arc<RwLock<u64>>,
}

impl AdaptiveTimeout {
    pub fn new(base_timeout_ms: u64) -> Self {
        Self {
            base_timeout_ms,
            current_timeout_ms: Arc::new(RwLock::new(base_timeout_ms)),
        }
    }

    pub async fn execute_with_timeout<F, T>(
        &self,
        operation: F,
    ) -> Result<T, String>
    where
        F: std::future::Future<Output = T>,
    {
        let timeout_ms = *self.current_timeout_ms.read().await;

        match timeout(Duration::from_millis(timeout_ms), operation).await {
            Ok(result) => {
                // Success - maybe decrease timeout
                self.adjust_timeout(0.95).await;
                Ok(result)
            }
            Err(_) => {
                // Timeout - increase timeout
                self.adjust_timeout(1.5).await;
                Err("Operation timed out".to_string())
            }
        }
    }

    async fn adjust_timeout(&self, factor: f64) {
        let mut current = self.current_timeout_ms.write().await;
        let new_timeout = (*current as f64 * factor) as u64;
        *current = new_timeout.clamp(self.base_timeout_ms / 2, self.base_timeout_ms * 4);
        tracing::debug!("Adjusted timeout to {}ms", *current);
    }
}

// Pattern 8: Complex select with multiple channels and timers
pub async fn multiplexed_event_handler() {
    let (data_tx, mut data_rx) = mpsc::channel::<String>(10);
    let (control_tx, mut control_rx) = mpsc::channel::<String>(10);
    let mut ticker = interval(Duration::from_secs(5));
    let mut shutdown_signal = tokio::signal::ctrl_c();

    // Spawn some producers
    tokio::spawn(async move {
        for i in 0..10 {
            sleep(Duration::from_millis(500)).await;
            let _ = data_tx.send(format!("Data {}", i)).await;
        }
    });

    tokio::spawn(async move {
        sleep(Duration::from_secs(3)).await;
        let _ = control_tx.send("status_check".to_string()).await;
    });

    loop {
        select! {
            Some(data) = data_rx.recv() => {
                tracing::info!("Received data: {}", data);
            }
            Some(control) = control_rx.recv() => {
                tracing::info!("Received control message: {}", control);
            }
            _ = ticker.tick() => {
                tracing::info!("Periodic health check");
            }
            _ = &mut shutdown_signal => {
                tracing::info!("Shutting down gracefully");
                break;
            }
        }
    }
}

// Example usage
#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    tracing_subscriber::fmt::init();

    // Pattern 1: Race
    tracing::info!("Racing operations...");
    let winner = race_operations().await;
    tracing::info!("Winner: {}", winner);

    // Pattern 2: Timeout with fallback
    let task = Task {
        id: "task-1".to_string(),
        duration_ms: 200,
    };
    let result = operation_with_timeout_and_fallback(task, 100).await?;
    tracing::info!("Result: {:?}", result);

    // Pattern 3: Graceful shutdown
    let worker = Worker::new(1000);
    sleep(Duration::from_secs(3)).await;
    worker.shutdown().await;

    // Pattern 4: Concurrent processing
    let tasks = vec![
        Task { id: "1".to_string(), duration_ms: 100 },
        Task { id: "2".to_string(), duration_ms: 150 },
        Task { id: "3".to_string(), duration_ms: 50 },
    ];
    let results = process_tasks_concurrently(tasks).await;
    tracing::info!("Processed {} tasks", results.len());

    // Pattern 6: Worker pool
    let (pool, mut result_rx) = WorkerPool::new(3);

    for i in 0..10 {
        pool.submit(Task {
            id: format!("task-{}", i),
            duration_ms: 100,
        }).await?;
    }

    // Collect results
    tokio::spawn(async move {
        while let Some(result) = result_rx.recv().await {
            tracing::info!("Task completed: {:?}", result);
        }
    });

    sleep(Duration::from_secs(2)).await;
    pool.shutdown().await;

    Ok(())
}

use bytes::{Bytes, BytesMut, Buf, BufMut};
use std::io::{self, Read, Write};

// Binary protocol parser
#[derive(Debug, Clone)]
pub struct MessageHeader {
    pub magic: u32,
    pub version: u8,
    pub message_type: u8,
    pub payload_length: u32,
}

impl MessageHeader {
    const SIZE: usize = 10; // 4 + 1 + 1 + 4

    pub fn new(message_type: u8, payload_length: u32) -> Self {
        Self {
            magic: 0xDEADBEEF,
            version: 1,
            message_type,
            payload_length,
        }
    }

    pub fn encode(&self, buf: &mut BytesMut) {
        buf.put_u32_le(self.magic);
        buf.put_u8(self.version);
        buf.put_u8(self.message_type);
        buf.put_u32_le(self.payload_length);
    }

    pub fn decode(buf: &mut impl Buf) -> Result<Self, &'static str> {
        if buf.remaining() < Self::SIZE {
            return Err("Insufficient bytes for header");
        }

        let magic = buf.get_u32_le();
        if magic != 0xDEADBEEF {
            return Err("Invalid magic number");
        }

        let version = buf.get_u8();
        let message_type = buf.get_u8();
        let payload_length = buf.get_u32_le();

        Ok(Self {
            magic,
            version,
            message_type,
            payload_length,
        })
    }
}

#[derive(Debug, Clone)]
pub struct Message {
    pub header: MessageHeader,
    pub payload: Bytes,
}

impl Message {
    pub fn new(message_type: u8, payload: Bytes) -> Self {
        let header = MessageHeader::new(message_type, payload.len() as u32);
        Self { header, payload }
    }

    pub fn encode(&self) -> BytesMut {
        let total_size = MessageHeader::SIZE + self.payload.len();
        let mut buf = BytesMut::with_capacity(total_size);

        self.header.encode(&mut buf);
        buf.put_slice(&self.payload);

        buf
    }

    pub fn decode(buf: &mut impl Buf) -> Result<Self, &'static str> {
        let header = MessageHeader::decode(buf)?;

        if buf.remaining() < header.payload_length as usize {
            return Err("Insufficient bytes for payload");
        }

        let payload = buf.copy_to_bytes(header.payload_length as usize);

        Ok(Self { header, payload })
    }
}

// Chunked data processor
pub struct ChunkedProcessor {
    buffer: BytesMut,
    chunk_size: usize,
}

impl ChunkedProcessor {
    pub fn new(chunk_size: usize) -> Self {
        Self {
            buffer: BytesMut::with_capacity(chunk_size * 2),
            chunk_size,
        }
    }

    pub fn push_data(&mut self, data: &[u8]) {
        self.buffer.put_slice(data);
    }

    pub fn process_chunks<F>(&mut self, mut processor: F) -> usize
    where
        F: FnMut(&[u8]),
    {
        let mut processed = 0;

        while self.buffer.len() >= self.chunk_size {
            let chunk = self.buffer.split_to(self.chunk_size);
            processor(&chunk);
            processed += 1;
        }

        processed
    }

    pub fn remaining(&self) -> usize {
        self.buffer.len()
    }

    pub fn flush<F>(&mut self, processor: F)
    where
        F: FnOnce(&[u8]),
    {
        if !self.buffer.is_empty() {
            processor(&self.buffer);
            self.buffer.clear();
        }
    }
}

// Binary serialization
pub trait BinarySerialize {
    fn serialize(&self, buf: &mut BytesMut);
    fn deserialize(buf: &mut impl Buf) -> Result<Self, &'static str>
    where
        Self: Sized;
}

#[derive(Debug, Clone, PartialEq)]
pub struct Point3D {
    pub x: f32,
    pub y: f32,
    pub z: f32,
}

impl BinarySerialize for Point3D {
    fn serialize(&self, buf: &mut BytesMut) {
        buf.put_f32_le(self.x);
        buf.put_f32_le(self.y);
        buf.put_f32_le(self.z);
    }

    fn deserialize(buf: &mut impl Buf) -> Result<Self, &'static str> {
        if buf.remaining() < 12 {
            return Err("Insufficient bytes for Point3D");
        }

        Ok(Self {
            x: buf.get_f32_le(),
            y: buf.get_f32_le(),
            z: buf.get_f32_le(),
        })
    }
}

// Length-prefixed string encoding
pub fn encode_string(s: &str, buf: &mut BytesMut) {
    let bytes = s.as_bytes();
    buf.put_u32_le(bytes.len() as u32);
    buf.put_slice(bytes);
}

pub fn decode_string(buf: &mut impl Buf) -> Result<String, &'static str> {
    if buf.remaining() < 4 {
        return Err("Insufficient bytes for string length");
    }

    let len = buf.get_u32_le() as usize;

    if buf.remaining() < len {
        return Err("Insufficient bytes for string data");
    }

    let bytes = buf.copy_to_bytes(len);
    String::from_utf8(bytes.to_vec())
        .map_err(|_| "Invalid UTF-8")
}

// Zero-copy buffer slicing
pub struct BufferReader {
    data: Bytes,
    position: usize,
}

impl BufferReader {
    pub fn new(data: Bytes) -> Self {
        Self { data, position: 0 }
    }

    pub fn read_slice(&mut self, len: usize) -> Option<Bytes> {
        if self.position + len > self.data.len() {
            return None;
        }

        let slice = self.data.slice(self.position..self.position + len);
        self.position += len;
        Some(slice)
    }

    pub fn read_u32_le(&mut self) -> Option<u32> {
        self.read_slice(4).map(|mut slice| slice.get_u32_le())
    }

    pub fn read_u64_le(&mut self) -> Option<u64> {
        self.read_slice(8).map(|mut slice| slice.get_u64_le())
    }

    pub fn remaining(&self) -> usize {
        self.data.len() - self.position
    }

    pub fn reset(&mut self) {
        self.position = 0;
    }
}

// Memory-efficient buffer pool
use std::sync::{Arc, Mutex};

pub struct BufferPool {
    pool: Arc<Mutex<Vec<BytesMut>>>,
    capacity: usize,
    max_size: usize,
}

impl BufferPool {
    pub fn new(capacity: usize, max_size: usize) -> Self {
        Self {
            pool: Arc::new(Mutex::new(Vec::new())),
            capacity,
            max_size,
        }
    }

    pub fn acquire(&self) -> BytesMut {
        let mut pool = self.pool.lock().unwrap();
        pool.pop()
            .unwrap_or_else(|| BytesMut::with_capacity(self.capacity))
    }

    pub fn release(&self, mut buffer: BytesMut) {
        buffer.clear();

        let mut pool = self.pool.lock().unwrap();
        if pool.len() < self.max_size {
            pool.push(buffer);
        }
    }
}

// Example usage
fn main() {
    // Message encoding/decoding
    let payload = Bytes::from("Hello, World!");
    let msg = Message::new(1, payload);

    let encoded = msg.encode();
    println!("Encoded message size: {} bytes", encoded.len());

    let mut buf = encoded.clone();
    let decoded = Message::decode(&mut buf).unwrap();
    println!("Decoded payload: {:?}", String::from_utf8_lossy(&decoded.payload));

    // Chunked processing
    let mut processor = ChunkedProcessor::new(10);
    processor.push_data(b"This is a test message that will be chunked");

    let chunks_processed = processor.process_chunks(|chunk| {
        println!("Processing chunk: {:?}", String::from_utf8_lossy(chunk));
    });

    println!("Processed {} chunks, {} bytes remaining", 
        chunks_processed, processor.remaining());

    // Binary serialization
    let point = Point3D { x: 1.0, y: 2.0, z: 3.0 };
    let mut buf = BytesMut::new();
    point.serialize(&mut buf);

    let mut read_buf = buf.clone();
    let decoded_point = Point3D::deserialize(&mut read_buf).unwrap();
    assert_eq!(point, decoded_point);

    // String encoding
    let mut buf = BytesMut::new();
    encode_string("Hello, Rust!", &mut buf);
    let decoded_str = decode_string(&mut buf).unwrap();
    println!("Decoded string: {}", decoded_str);

    // Zero-copy reading
    let data = Bytes::from(&b"ABCD"[..]);
    let mut reader = BufferReader::new(data);

    if let Some(slice) = reader.read_slice(4) {
        println!("Read slice: {:?}", String::from_utf8_lossy(&slice));
    }

    if let Some(num1) = reader.read_u32_le() {
        println!("Read u32: {}", num1);
    }

    // Buffer pool
    let pool = BufferPool::new(1024, 10);
    let buf1 = pool.acquire();
    let buf2 = pool.acquire();

    pool.release(buf1);
    pool.release(buf2);
}

use crossbeam::{
    channel::{bounded, unbounded, select, Sender, Receiver},
    thread,
};
use std::sync::Arc;
use std::sync::atomic::{AtomicU64, AtomicBool, Ordering};
use std::time::Duration;

// Lock-free counter
pub struct Counter {
    value: AtomicU64,
}

impl Counter {
    pub fn new() -> Self {
        Self {
            value: AtomicU64::new(0),
        }
    }

    pub fn increment(&self) -> u64 {
        self.value.fetch_add(1, Ordering::SeqCst)
    }

    pub fn get(&self) -> u64 {
        self.value.load(Ordering::SeqCst)
    }
}

// Multi-producer, multi-consumer queue
pub struct WorkQueue<T> {
    sender: Sender<T>,
    receiver: Receiver<T>,
    shutdown: Arc<AtomicBool>,
}

impl<T: Send + 'static> WorkQueue<T> {
    pub fn new(capacity: usize) -> Self {
        let (sender, receiver) = bounded(capacity);
        Self {
            sender,
            receiver,
            shutdown: Arc::new(AtomicBool::new(false)),
        }
    }

    pub fn sender(&self) -> Sender<T> {
        self.sender.clone()
    }

    pub fn spawn_workers<F>(&self, num_workers: usize, mut work_fn: F)
    where
        F: FnMut(T) + Send + Clone + 'static,
    {
        let receiver = self.receiver.clone();
        let shutdown = self.shutdown.clone();

        for id in 0..num_workers {
            let receiver = receiver.clone();
            let shutdown = shutdown.clone();
            let mut work_fn = work_fn.clone();

            thread::spawn(move || {
                println!("Worker {} started", id);

                while !shutdown.load(Ordering::Relaxed) {
                    match receiver.recv_timeout(Duration::from_millis(100)) {
                        Ok(item) => {
                            work_fn(item);
                        }
                        Err(crossbeam::channel::RecvTimeoutError::Timeout) => continue,
                        Err(crossbeam::channel::RecvTimeoutError::Disconnected) => break,
                    }
                }

                println!("Worker {} stopped", id);
            });
        }
    }

    pub fn shutdown(&self) {
        self.shutdown.store(true, Ordering::Relaxed);
    }
}

// Select pattern for multiple channels
pub fn multiplexed_receiver<T: Send>(receivers: Vec<Receiver<T>>) -> Vec<T> {
    let mut results = Vec::new();
    let mut active_receivers = receivers;

    loop {
        let mut sel = select! {};

        for (idx, rx) in active_receivers.iter().enumerate() {
            sel = sel.recv(rx, move |msg| (idx, msg));
        }

        match sel {
            Ok((idx, Ok(value))) => {
                results.push(value);
            }
            Ok((idx, Err(_))) => {
                active_receivers.remove(idx);
                if active_receivers.is_empty() {
                    break;
                }
            }
            Err(_) => break,
        }
    }

    results
}

// Pipeline pattern
pub fn create_pipeline() {
    let (input_tx, input_rx) = unbounded::<i32>();
    let (stage1_tx, stage1_rx) = unbounded::<i32>();
    let (stage2_tx, stage2_rx) = unbounded::<i32>();

    // Stage 1: Double the input
    thread::spawn(move || {
        for num in input_rx {
            let result = num * 2;
            println!("Stage 1: {} -> {}", num, result);
            let _ = stage1_tx.send(result);
        }
    });

    // Stage 2: Add 10
    thread::spawn(move || {
        for num in stage1_rx {
            let result = num + 10;
            println!("Stage 2: {} -> {}", num, result);
            let _ = stage2_tx.send(result);
        }
    });

    // Output consumer
    thread::spawn(move || {
        for result in stage2_rx {
            println!("Final result: {}", result);
        }
    });

    // Send some data through the pipeline
    for i in 1..=5 {
        input_tx.send(i).unwrap();
    }

    drop(input_tx); // Close the pipeline

    thread::sleep(Duration::from_secs(1));
}

// Fan-out / Fan-in pattern
pub fn fan_out_fan_in() {
    let (input_tx, input_rx) = unbounded::<i32>();
    let output_receivers: Vec<_> = (0..3)
        .map(|worker_id| {
            let (tx, rx) = unbounded();
            let input_rx = input_rx.clone();

            thread::spawn(move || {
                for num in input_rx {
                    let result = num * worker_id;
                    println!("Worker {} processed: {}", worker_id, result);
                    thread::sleep(Duration::from_millis(100));
                    let _ = tx.send(result);
                }
            });

            rx
        })
        .collect();

    drop(input_rx);

    // Fan-in: collect results from all workers
    thread::spawn(move || {
        let results = multiplexed_receiver(output_receivers);
        println!("Collected {} results", results.len());
        for result in results {
            println!("Result: {}", result);
        }
    });

    // Send work
    for i in 1..=10 {
        input_tx.send(i).unwrap();
    }

    drop(input_tx);
    thread::sleep(Duration::from_secs(2));
}

fn main() {
    // Lock-free counter
    let counter = Arc::new(Counter::new());
    let handles: Vec<_> = (0..10)
        .map(|_| {
            let counter = counter.clone();
            thread::spawn(move || {
                for _ in 0..1000 {
                    counter.increment();
                }
            })
        })
        .collect();

    for handle in handles {
        handle.join().unwrap();
    }

    println!("Final count: {}", counter.get());

    // Work queue
    let queue = WorkQueue::new(10);
    queue.spawn_workers(3, |item: i32| {
        println!("Processing item: {}", item);
        thread::sleep(Duration::from_millis(100));
    });

    let sender = queue.sender();
    for i in 0..20 {
        sender.send(i).unwrap();
    }

    thread::sleep(Duration::from_secs(3));
    queue.shutdown();

    // Pipeline
    println!("
Running pipeline...");
    create_pipeline();

    // Fan-out/Fan-in
    println!("
Running fan-out/fan-in...");
    fan_out_fan_in();
}

use reqwest::{Client, ClientBuilder, StatusCode};
use serde::{Deserialize, Serialize};
use std::time::Duration;
use thiserror::Error;
use tokio::time::sleep;

#[derive(Debug, Error)]
pub enum ApiError {
    #[error("HTTP request failed: {0}")]
    RequestFailed(#[from] reqwest::Error),

    #[error("API returned error: {status} - {message}")]
    ApiError { status: StatusCode, message: String },

    #[error("Serialization error: {0}")]
    SerializationError(#[from] serde_json::Error),

    #[error("Timeout after {0} retries")]
    MaxRetriesExceeded(u32),

    #[error("Rate limit exceeded, retry after {0} seconds")]
    RateLimitExceeded(u64),
}

pub type Result<T> = std::result::Result<T, ApiError>;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ApiResponse<T> {
    pub success: bool,
    pub data: Option<T>,
    pub error: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct User {
    pub id: String,
    pub name: String,
    pub email: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CreateUserRequest {
    pub name: String,
    pub email: String,
}

#[derive(Debug, Clone)]
pub struct RetryConfig {
    pub max_retries: u32,
    pub base_delay_ms: u64,
    pub max_delay_ms: u64,
    pub exponential_backoff: bool,
}

impl Default for RetryConfig {
    fn default() -> Self {
        Self {
            max_retries: 3,
            base_delay_ms: 1000,
            max_delay_ms: 30000,
            exponential_backoff: true,
        }
    }
}

pub struct ApiClient {
    client: Client,
    base_url: String,
    api_key: Option<String>,
    retry_config: RetryConfig,
}

impl ApiClient {
    pub fn new(base_url: impl Into<String>) -> Result<Self> {
        let client = ClientBuilder::new()
            .timeout(Duration::from_secs(30))
            .connect_timeout(Duration::from_secs(10))
            .pool_idle_timeout(Duration::from_secs(90))
            .pool_max_idle_per_host(10)
            .build()?;

        Ok(Self {
            client,
            base_url: base_url.into(),
            api_key: None,
            retry_config: RetryConfig::default(),
        })
    }

    pub fn with_api_key(mut self, api_key: impl Into<String>) -> Self {
        self.api_key = Some(api_key.into());
        self
    }

    pub fn with_retry_config(mut self, config: RetryConfig) -> Self {
        self.retry_config = config;
        self
    }

    async fn execute_with_retry<F, Fut, T>(
        &self,
        operation: F,
    ) -> Result<T>
    where
        F: Fn() -> Fut,
        Fut: std::future::Future<Output = Result<T>>,
    {
        let mut attempts = 0;
        let mut last_error = None;

        while attempts <= self.retry_config.max_retries {
            match operation().await {
                Ok(result) => return Ok(result),
                Err(e) => {
                    last_error = Some(e);
                    attempts += 1;

                    if attempts > self.retry_config.max_retries {
                        break;
                    }

                    // Calculate delay with exponential backoff
                    let delay = if self.retry_config.exponential_backoff {
                        let exp_delay = self.retry_config.base_delay_ms * 2_u64.pow(attempts - 1);
                        exp_delay.min(self.retry_config.max_delay_ms)
                    } else {
                        self.retry_config.base_delay_ms
                    };

                    tracing::warn!(
                        "Request failed (attempt {}/{}), retrying in {}ms",
                        attempts,
                        self.retry_config.max_retries,
                        delay
                    );

                    sleep(Duration::from_millis(delay)).await;
                }
            }
        }

        Err(last_error.unwrap_or(ApiError::MaxRetriesExceeded(self.retry_config.max_retries)))
    }

    fn build_request(&self, method: reqwest::Method, path: &str) -> reqwest::RequestBuilder {
        let url = format!("{}{}", self.base_url, path);
        let mut builder = self.client.request(method, &url)
            .header("Content-Type", "application/json")
            .header("Accept", "application/json");

        if let Some(api_key) = &self.api_key {
            builder = builder.header("Authorization", format!("Bearer {}", api_key));
        }

        builder
    }

    async fn handle_response<T: for<'de> Deserialize<'de>>(
        &self,
        response: reqwest::Response,
    ) -> Result<T> {
        let status = response.status();

        if status == StatusCode::TOO_MANY_REQUESTS {
            let retry_after = response
                .headers()
                .get("Retry-After")
                .and_then(|h| h.to_str().ok())
                .and_then(|s| s.parse::<u64>().ok())
                .unwrap_or(60);

            return Err(ApiError::RateLimitExceeded(retry_after));
        }

        if !status.is_success() {
            let error_body = response.text().await.unwrap_or_else(|_| "Unknown error".to_string());
            return Err(ApiError::ApiError {
                status,
                message: error_body,
            });
        }

        let body = response.bytes().await?;
        let data = serde_json::from_slice(&body)?;

        Ok(data)
    }

    pub async fn get<T: for<'de> Deserialize<'de>>(&self, path: &str) -> Result<T> {
        self.execute_with_retry(|| async {
            let response = self.build_request(reqwest::Method::GET, path)
                .send()
                .await?;

            self.handle_response(response).await
        }).await
    }

    pub async fn post<B: Serialize, T: for<'de> Deserialize<'de>>(
        &self,
        path: &str,
        body: &B,
    ) -> Result<T> {
        self.execute_with_retry(|| async {
            let response = self.build_request(reqwest::Method::POST, path)
                .json(body)
                .send()
                .await?;

            self.handle_response(response).await
        }).await
    }

    pub async fn put<B: Serialize, T: for<'de> Deserialize<'de>>(
        &self,
        path: &str,
        body: &B,
    ) -> Result<T> {
        self.execute_with_retry(|| async {
            let response = self.build_request(reqwest::Method::PUT, path)
                .json(body)
                .send()
                .await?;

            self.handle_response(response).await
        }).await
    }

    pub async fn delete(&self, path: &str) -> Result<()> {
        self.execute_with_retry(|| async {
            let response = self.build_request(reqwest::Method::DELETE, path)
                .send()
                .await?;

            let status = response.status();
            if !status.is_success() {
                let error_body = response.text().await.unwrap_or_else(|_| "Unknown error".to_string());
                return Err(ApiError::ApiError {
                    status,
                    message: error_body,
                });
            }

            Ok(())
        }).await
    }

    // High-level API methods
    pub async fn get_user(&self, user_id: &str) -> Result<User> {
        let response: ApiResponse<User> = self.get(&format!("/users/{}", user_id)).await?;
        response.data.ok_or_else(|| ApiError::ApiError {
            status: StatusCode::NOT_FOUND,
            message: response.error.unwrap_or_else(|| "User not found".to_string()),
        })
    }

    pub async fn list_users(&self, page: u32, limit: u32) -> Result<Vec<User>> {
        let response: ApiResponse<Vec<User>> = self
            .get(&format!("/users?page={}&limit={}", page, limit))
            .await?;

        response.data.ok_or_else(|| ApiError::ApiError {
            status: StatusCode::INTERNAL_SERVER_ERROR,
            message: response.error.unwrap_or_else(|| "Failed to fetch users".to_string()),
        })
    }

    pub async fn create_user(&self, request: CreateUserRequest) -> Result<User> {
        let response: ApiResponse<User> = self.post("/users", &request).await?;
        response.data.ok_or_else(|| ApiError::ApiError {
            status: StatusCode::BAD_REQUEST,
            message: response.error.unwrap_or_else(|| "Failed to create user".to_string()),
        })
    }

    pub async fn update_user(&self, user_id: &str, request: CreateUserRequest) -> Result<User> {
        let response: ApiResponse<User> = self
            .put(&format!("/users/{}", user_id), &request)
            .await?;

        response.data.ok_or_else(|| ApiError::ApiError {
            status: StatusCode::BAD_REQUEST,
            message: response.error.unwrap_or_else(|| "Failed to update user".to_string()),
        })
    }

    pub async fn delete_user(&self, user_id: &str) -> Result<()> {
        self.delete(&format!("/users/{}", user_id)).await
    }

    // Batch operations with concurrency control
    pub async fn batch_get_users(&self, user_ids: Vec<String>, concurrency: usize) -> Vec<Result<User>> {
        use futures::stream::{self, StreamExt};

        stream::iter(user_ids)
            .map(|id| async move {
                self.get_user(&id).await
            })
            .buffer_unordered(concurrency)
            .collect()
            .await
    }
}

