// Building a service with multiple middleware layers
pub async fn build_service() {
    let service = ServiceBuilder::new()
        // Add timeout layer
        .layer(TimeoutLayer::new(Duration::from_secs(30)))
        // Add rate limiting
        .layer(RateLimitLayer::new(5, Duration::from_secs(1)))
        // Add buffering
        .layer(BufferLayer::new(100))
        // Add custom logging
        .layer(LoggingLayer)
        // Add custom auth
        .layer(AuthLayer::new(vec!["valid_token".to_string()]))
        // Build the service
        .service(EchoService);

    // Use the service
    let mut service = service;

    let request = HttpRequest {
        path: "/api/users".to_string(),
        token: "valid_token".to_string(),
    };

    match service.ready().await {
        Ok(svc) => {
            match svc.call(request).await {
                Ok(response) => println!("Response: {}", response),
                Err(e) => println!("Error: {}", e),
            }
        }
        Err(e) => println!("Service not ready: {}", e),
    }
}

// Retry middleware
#[derive(Clone)]
pub struct RetryLayer {
    max_retries: usize,
}

impl RetryLayer {
    pub fn new(max_retries: usize) -> Self {
        Self { max_retries }
    }
}

impl<S> Layer<S> for RetryLayer {
    type Service = RetryService<S>;

    fn layer(&self, service: S) -> Self::Service {
        RetryService {
            inner: service,
            max_retries: self.max_retries,
        }
    }
}

#[derive(Clone)]
pub struct RetryService<S> {
    inner: S,
    max_retries: usize,
}

impl<S, Request> Service<Request> for RetryService<S>
where
    S: Service<Request> + Clone,
    Request: Clone,
{
    type Response = S::Response;
    type Error = S::Error;
    type Future = Pin<Box<dyn Future<Output = Result<Self::Response, Self::Error>> + Send>>;

    fn poll_ready(&mut self, cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        self.inner.poll_ready(cx)
    }

    fn call(&mut self, request: Request) -> Self::Future {
        let mut service = self.inner.clone();
        let max_retries = self.max_retries;

        Box::pin(async move {
            let mut attempts = 0;
            loop {
                let req = request.clone();
                match service.call(req).await {
                    Ok(response) => return Ok(response),
                    Err(e) => {
                        attempts += 1;
                        if attempts >= max_retries {
                            return Err(e);
                        }
                        println!("Retry attempt {}/{}", attempts, max_retries);
                        tokio::time::sleep(Duration::from_millis(100 * attempts as u64)).await;
                    }
                }
            }
        })
    }
}

#[tokio::main]
async fn main() {
    build_service().await;
}

use parking_lot::{Mutex, RwLock, Condvar, Once, OnceState};
use std::sync::Arc;
use std::thread;
use std::time::Duration;

// Shared counter with Mutex
#[derive(Default)]
pub struct Counter {
    value: Mutex<u64>,
}

impl Counter {
    pub fn new() -> Self {
        Self {
            value: Mutex::new(0),
        }
    }

    pub fn increment(&self) {
        let mut val = self.value.lock();
        *val += 1;
    }

    pub fn get(&self) -> u64 {
        *self.value.lock()
    }

    pub fn increment_by(&self, amount: u64) {
        let mut val = self.value.lock();
        *val += amount;
    }
}

// Read-write cache with RwLock
pub struct Cache<K, V> {
    data: RwLock<std::collections::HashMap<K, V>>,
}

impl<K: Eq + std::hash::Hash + Clone, V: Clone> Cache<K, V> {
    pub fn new() -> Self {
        Self {
            data: RwLock::new(std::collections::HashMap::new()),
        }
    }

    pub fn get(&self, key: &K) -> Option<V> {
        // Multiple readers can access simultaneously
        let data = self.data.read();
        data.get(key).cloned()
    }

    pub fn insert(&self, key: K, value: V) -> Option<V> {
        // Exclusive write access
        let mut data = self.data.write();
        data.insert(key, value)
    }

    pub fn remove(&self, key: &K) -> Option<V> {
        let mut data = self.data.write();
        data.remove(key)
    }

    pub fn contains_key(&self, key: &K) -> bool {
        let data = self.data.read();
        data.contains_key(key)
    }

    pub fn len(&self) -> usize {
        let data = self.data.read();
        data.len()
    }

    pub fn clear(&self) {
        let mut data = self.data.write();
        data.clear();
    }
}

// Producer-Consumer with Condvar
pub struct BoundedQueue<T> {
    queue: Mutex<std::collections::VecDeque<T>>,
    not_empty: Condvar,
    not_full: Condvar,
    capacity: usize,
}

impl<T> BoundedQueue<T> {
    pub fn new(capacity: usize) -> Self {
        Self {
            queue: Mutex::new(std::collections::VecDeque::with_capacity(capacity)),
            not_empty: Condvar::new(),
            not_full: Condvar::new(),
            capacity,
        }
    }

    pub fn push(&self, item: T) {
        let mut queue = self.queue.lock();

        // Wait until there's space
        while queue.len() >= self.capacity {
            self.not_full.wait(&mut queue);
        }

        queue.push_back(item);
        self.not_empty.notify_one();
    }

    pub fn pop(&self) -> T {
        let mut queue = self.queue.lock();

        // Wait until there's an item
        while queue.is_empty() {
            self.not_empty.wait(&mut queue);
        }

        let item = queue.pop_front().unwrap();
        self.not_full.notify_one();
        item
    }

    pub fn try_push(&self, item: T) -> Result<(), T> {
        let mut queue = self.queue.lock();

        if queue.len() >= self.capacity {
            return Err(item);
        }

        queue.push_back(item);
        self.not_empty.notify_one();
        Ok(())
    }

    pub fn try_pop(&self) -> Option<T> {
        let mut queue = self.queue.lock();

        if queue.is_empty() {
            return None;
        }

        let item = queue.pop_front();
        self.not_full.notify_one();
        item
    }

    pub fn len(&self) -> usize {
        self.queue.lock().len()
    }
}

// Lazy initialization with Once
pub struct LazyResource {
    once: Once,
    resource: RwLock<Option<String>>,
}

impl LazyResource {
    pub fn new() -> Self {
        Self {
            once: Once::new(),
            resource: RwLock::new(None),
        }
    }

    pub fn get(&self) -> String {
        self.once.call_once(|| {
            println!("Initializing resource...");
            thread::sleep(Duration::from_millis(100));
            *self.resource.write() = Some("Initialized Resource".to_string());
        });

        self.resource.read().as_ref().unwrap().clone()
    }

    pub fn is_initialized(&self) -> bool {
        self.once.state() == OnceState::Done
    }
}

// Thread-safe event log
pub struct EventLog {
    events: Mutex<Vec<(chrono::DateTime<chrono::Utc>, String)>>,
    max_events: usize,
}

impl EventLog {
    pub fn new(max_events: usize) -> Self {
        Self {
            events: Mutex::new(Vec::with_capacity(max_events)),
            max_events,
        }
    }

    pub fn log(&self, message: impl Into<String>) {
        let mut events = self.events.lock();

        if events.len() >= self.max_events {
            events.remove(0);
        }

        events.push((chrono::Utc::now(), message.into()));
    }

    pub fn get_recent(&self, count: usize) -> Vec<(chrono::DateTime<chrono::Utc>, String)> {
        let events = self.events.lock();
        let start = events.len().saturating_sub(count);
        events[start..].to_vec()
    }

    pub fn clear(&self) {
        let mut events = self.events.lock();
        events.clear();
    }
}

// Connection pool with RwLock
pub struct ConnectionPool {
    connections: RwLock<Vec<String>>,
    max_size: usize,
}

impl ConnectionPool {
    pub fn new(max_size: usize) -> Self {
        Self {
            connections: RwLock::new(Vec::new()),
            max_size,
        }
    }

    pub fn acquire(&self) -> Option<String> {
        let mut connections = self.connections.write();
        connections.pop()
    }

    pub fn release(&self, connection: String) -> Result<(), String> {
        let mut connections = self.connections.write();

        if connections.len() >= self.max_size {
            return Err("Pool is full".to_string());
        }

        connections.push(connection);
        Ok(())
    }

    pub fn size(&self) -> usize {
        self.connections.read().len()
    }
}

// Example usage
fn main() {
    // Counter example
    let counter = Arc::new(Counter::new());
    let handles: Vec<_> = (0..10)
        .map(|_| {
            let counter = counter.clone();
            thread::spawn(move || {
                for _ in 0..1000 {
                    counter.increment();
                }
            })
        })
        .collect();

    for handle in handles {
        handle.join().unwrap();
    }

    println!("Final counter value: {}", counter.get());

    // Cache example
    let cache = Arc::new(Cache::<String, i32>::new());

    cache.insert("key1".to_string(), 42);
    cache.insert("key2".to_string(), 84);

    println!("Cache get key1: {:?}", cache.get(&"key1".to_string()));
    println!("Cache size: {}", cache.len());

    // Bounded queue example
    let queue = Arc::new(BoundedQueue::new(5));

    let producer_queue = queue.clone();
    let producer = thread::spawn(move || {
        for i in 0..10 {
            producer_queue.push(i);
            println!("Produced: {}", i);
            thread::sleep(Duration::from_millis(50));
        }
    });

    let consumer_queue = queue.clone();
    let consumer = thread::spawn(move || {
        for _ in 0..10 {
            let item = consumer_queue.pop();
            println!("Consumed: {}", item);
            thread::sleep(Duration::from_millis(100));
        }
    });

    producer.join().unwrap();
    consumer.join().unwrap();

    // Lazy resource example
    let resource = Arc::new(LazyResource::new());

    println!("Is initialized: {}", resource.is_initialized());

    let handles: Vec<_> = (0..3)
        .map(|i| {
            let resource = resource.clone();
            thread::spawn(move || {
                println!("Thread {}: {}", i, resource.get());
            })
        })
        .collect();

    for handle in handles {
        handle.join().unwrap();
    }

    // Event log example
    let log = Arc::new(EventLog::new(100));

    log.log("Application started");
    log.log("Processing data");
    log.log("Operation completed");

    println!("
Recent events:");
    for (timestamp, message) in log.get_recent(3) {
        println!("  [{}] {}", timestamp.format("%H:%M:%S"), message);
    }
}

use csv::{Reader, Writer, StringRecord};
use serde::{Deserialize, Serialize};
use std::error::Error;
use std::io;

#[derive(Debug, Deserialize, Serialize, Clone)]
pub struct Customer {
    pub id: u32,
    pub name: String,
    pub email: String,
    pub age: u32,
    pub country: String,
}

#[derive(Debug, Deserialize, Serialize)]
pub struct Order {
    pub order_id: u32,
    pub customer_id: u32,
    pub product: String,
    pub quantity: u32,
    pub price: f64,
}

// Read CSV into structs
pub fn read_customers(path: &str) -> Result<Vec<Customer>, Box<dyn Error>> {
    let mut reader = Reader::from_path(path)?;
    let mut customers = Vec::new();

    for result in reader.deserialize() {
        let customer: Customer = result?;
        customers.push(customer);
    }

    Ok(customers)
}

// Write structs to CSV
pub fn write_customers(path: &str, customers: &[Customer]) -> Result<(), Box<dyn Error>> {
    let mut writer = Writer::from_path(path)?;

    for customer in customers {
        writer.serialize(customer)?;
    }

    writer.flush()?;
    Ok(())
}

// Stream processing for large files
pub fn process_large_csv<F>(
    input_path: &str,
    output_path: &str,
    mut processor: F,
) -> Result<usize, Box<dyn Error>>
where
    F: FnMut(&mut Customer) -> bool,
{
    let mut reader = Reader::from_path(input_path)?;
    let mut writer = Writer::from_path(output_path)?;
    let mut processed_count = 0;

    for result in reader.deserialize() {
        let mut customer: Customer = result?;

        if processor(&mut customer) {
            writer.serialize(&customer)?;
            processed_count += 1;
        }
    }

    writer.flush()?;
    Ok(processed_count)
}

// Aggregate data from CSV
pub fn aggregate_by_country(path: &str) -> Result<std::collections::HashMap<String, Vec<Customer>>, Box<dyn Error>> {
    let customers = read_customers(path)?;
    let mut by_country = std::collections::HashMap::new();

    for customer in customers {
        by_country
            .entry(customer.country.clone())
            .or_insert_with(Vec::new)
            .push(customer);
    }

    Ok(by_country)
}

// Join two CSV files
pub fn join_customers_orders(
    customers_path: &str,
    orders_path: &str,
) -> Result<Vec<(Customer, Vec<Order>)>, Box<dyn Error>> {
    let customers = read_customers(customers_path)?;
    let mut orders_reader = Reader::from_path(orders_path)?;

    let mut orders_by_customer: std::collections::HashMap<u32, Vec<Order>> = std::collections::HashMap::new();

    for result in orders_reader.deserialize() {
        let order: Order = result?;
        orders_by_customer
            .entry(order.customer_id)
            .or_insert_with(Vec::new)
            .push(order);
    }

    let joined: Vec<_> = customers
        .into_iter()
        .map(|customer| {
            let orders = orders_by_customer
                .remove(&customer.id)
                .unwrap_or_default();
            (customer, orders)
        })
        .collect();

    Ok(joined)
}

// CSV transformation with custom delimiter
pub fn convert_delimiter(
    input_path: &str,
    output_path: &str,
    input_delimiter: u8,
    output_delimiter: u8,
) -> Result<(), Box<dyn Error>> {
    let mut reader = csv::ReaderBuilder::new()
        .delimiter(input_delimiter)
        .from_path(input_path)?;

    let mut writer = csv::WriterBuilder::new()
        .delimiter(output_delimiter)
        .from_path(output_path)?;

    // Write headers
    let headers = reader.headers()?.clone();
    writer.write_record(&headers)?;

    // Copy all records
    for result in reader.records() {
        let record = result?;
        writer.write_record(&record)?;
    }

    writer.flush()?;
    Ok(())
}

// Statistics from CSV
#[derive(Debug)]
pub struct Statistics {
    pub count: usize,
    pub avg_age: f64,
    pub min_age: u32,
    pub max_age: u32,
}

pub fn calculate_statistics(path: &str) -> Result<Statistics, Box<dyn Error>> {
    let customers = read_customers(path)?;

    if customers.is_empty() {
        return Ok(Statistics {
            count: 0,
            avg_age: 0.0,
            min_age: 0,
            max_age: 0,
        });
    }

    let sum: u32 = customers.iter().map(|c| c.age).sum();
    let avg_age = sum as f64 / customers.len() as f64;
    let min_age = customers.iter().map(|c| c.age).min().unwrap();
    let max_age = customers.iter().map(|c| c.age).max().unwrap();

    Ok(Statistics {
        count: customers.len(),
        avg_age,
        min_age,
        max_age,
    })
}

// Filter and export
pub fn export_filtered(
    path: &str,
    output_path: &str,
    min_age: u32,
    country: Option<&str>,
) -> Result<usize, Box<dyn Error>> {
    process_large_csv(path, output_path, |customer| {
        let age_ok = customer.age >= min_age;
        let country_ok = country.map_or(true, |c| customer.country == c);
        age_ok && country_ok
    })
}

// Parallel CSV processing
use rayon::prelude::*;

pub fn parallel_process_csv(path: &str) -> Result<Vec<Customer>, Box<dyn Error>> {
    let customers = read_customers(path)?;

    let processed: Vec<_> = customers
        .into_par_iter()
        .map(|mut customer| {
            // Simulate expensive processing
            customer.email = customer.email.to_lowercase();
            customer.name = customer.name.trim().to_string();
            customer
        })
        .collect();

    Ok(processed)
}

// Example usage
fn main() -> Result<(), Box<dyn Error>> {
    // Create sample data
    let customers = vec![
        Customer {
            id: 1,
            name: "John Doe".to_string(),
            email: "john@example.com".to_string(),
            age: 30,
            country: "USA".to_string(),
        },
        Customer {
            id: 2,
            name: "Jane Smith".to_string(),
            email: "jane@example.com".to_string(),
            age: 25,
            country: "UK".to_string(),
        },
        Customer {
            id: 3,
            name: "Bob Johnson".to_string(),
            email: "bob@example.com".to_string(),
            age: 35,
            country: "USA".to_string(),
        },
    ];

    // Write to CSV
    write_customers("customers.csv", &customers)?;
    println!("Wrote {} customers", customers.len());

    // Read from CSV
    let loaded = read_customers("customers.csv")?;
    println!("Loaded {} customers", loaded.len());

    // Calculate statistics
    let stats = calculate_statistics("customers.csv")?;
    println!("Statistics: {:?}", stats);

    // Group by country
    let by_country = aggregate_by_country("customers.csv")?;
    for (country, customers) in by_country {
        println!("{}: {} customers", country, customers.len());
    }

    // Export filtered data
    let filtered_count = export_filtered("customers.csv", "filtered.csv", 28, Some("USA"))?;
    println!("Exported {} filtered customers", filtered_count);

    Ok(())
}

