// Repository trait
#[async_trait]
pub trait Repository<T> {
    async fn find_by_id(&self, id: i32) -> Result<T>;
    async fn find_all(&self, limit: i64, offset: i64) -> Result<Vec<T>>;
    async fn count(&self) -> Result<i64>;
}

// User repository
pub struct UserRepository {
    pool: PgPool,
}

impl UserRepository {
    pub fn new(pool: PgPool) -> Self {
        Self { pool }
    }

    pub async fn create(&self, dto: CreateUserDto) -> Result<User> {
        let password_hash = Self::hash_password(&dto.password);

        let user = sqlx::query_as!(
            User,
            r#"
            INSERT INTO users (email, username, password_hash, is_active)
            VALUES ($1, $2, $3, true)
            RETURNING id, email, username, password_hash, is_active, created_at, updated_at
            "#,
            dto.email,
            dto.username,
            password_hash
        )
        .fetch_one(&self.pool)
        .await
        .map_err(|e| {
            if e.to_string().contains("duplicate key") {
                RepositoryError::DuplicateEntry("Email or username already exists".to_string())
            } else {
                RepositoryError::Database(e)
            }
        })?;

        Ok(user)
    }

    pub async fn update(&self, id: i32, dto: UpdateUserDto) -> Result<User> {
        let user = sqlx::query_as!(
            User,
            r#"
            UPDATE users
            SET 
                email = COALESCE($1, email),
                username = COALESCE($2, username),
                is_active = COALESCE($3, is_active),
                updated_at = NOW()
            WHERE id = $4
            RETURNING id, email, username, password_hash, is_active, created_at, updated_at
            "#,
            dto.email,
            dto.username,
            dto.is_active,
            id
        )
        .fetch_optional(&self.pool)
        .await?
        .ok_or(RepositoryError::NotFound)?;

        Ok(user)
    }

    pub async fn find_by_email(&self, email: &str) -> Result<User> {
        let user = sqlx::query_as!(
            User,
            "SELECT id, email, username, password_hash, is_active, created_at, updated_at 
             FROM users WHERE email = $1",
            email
        )
        .fetch_optional(&self.pool)
        .await?
        .ok_or(RepositoryError::NotFound)?;

        Ok(user)
    }

    pub async fn find_by_username(&self, username: &str) -> Result<User> {
        let user = sqlx::query_as!(
            User,
            "SELECT id, email, username, password_hash, is_active, created_at, updated_at 
             FROM users WHERE username = $1",
            username
        )
        .fetch_optional(&self.pool)
        .await?
        .ok_or(RepositoryError::NotFound)?;

        Ok(user)
    }

    pub async fn delete(&self, id: i32) -> Result<()> {
        let result = sqlx::query!("DELETE FROM users WHERE id = $1", id)
            .execute(&self.pool)
            .await?;

        if result.rows_affected() == 0 {
            return Err(RepositoryError::NotFound);
        }

        Ok(())
    }

    fn hash_password(password: &str) -> String {
        // In production, use a proper password hashing library like argon2
        format!("hashed_{}", password)
    }
}

#[async_trait]
impl Repository<User> for UserRepository {
    async fn find_by_id(&self, id: i32) -> Result<User> {
        let user = sqlx::query_as!(
            User,
            "SELECT id, email, username, password_hash, is_active, created_at, updated_at 
             FROM users WHERE id = $1",
            id
        )
        .fetch_optional(&self.pool)
        .await?
        .ok_or(RepositoryError::NotFound)?;

        Ok(user)
    }

    async fn find_all(&self, limit: i64, offset: i64) -> Result<Vec<User>> {
        let users = sqlx::query_as!(
            User,
            "SELECT id, email, username, password_hash, is_active, created_at, updated_at 
             FROM users ORDER BY created_at DESC LIMIT $1 OFFSET $2",
            limit,
            offset
        )
        .fetch_all(&self.pool)
        .await?;

        Ok(users)
    }

    async fn count(&self) -> Result<i64> {
        let count = sqlx::query!("SELECT COUNT(*) as count FROM users")
            .fetch_one(&self.pool)
            .await?
            .count
            .unwrap_or(0);

        Ok(count)
    }
}

// Post repository with complex queries
pub struct PostRepository {
    pool: PgPool,
}

impl PostRepository {
    pub fn new(pool: PgPool) -> Self {
        Self { pool }
    }

    pub async fn create(&self, dto: CreatePostDto) -> Result<Post> {
        let post = sqlx::query_as!(
            Post,
            r#"
            INSERT INTO posts (user_id, title, content, published, view_count)
            VALUES ($1, $2, $3, $4, 0)
            RETURNING id, user_id, title, content, published, view_count, created_at, updated_at
            "#,
            dto.user_id,
            dto.title,
            dto.content,
            dto.published
        )
        .fetch_one(&self.pool)
        .await?;

        Ok(post)
    }

    pub async fn find_with_user(&self, id: i32) -> Result<(Post, User)> {
        let row = sqlx::query!(
            r#"
            SELECT 
                p.id, p.user_id, p.title, p.content, p.published, p.view_count,
                p.created_at as post_created_at, p.updated_at as post_updated_at,
                u.id as user_id, u.email, u.username, u.password_hash, u.is_active,
                u.created_at as user_created_at, u.updated_at as user_updated_at
            FROM posts p
            INNER JOIN users u ON p.user_id = u.id
            WHERE p.id = $1
            "#,
            id
        )
        .fetch_optional(&self.pool)
        .await?
        .ok_or(RepositoryError::NotFound)?;

        let post = Post {
            id: row.id,
            user_id: row.user_id,
            title: row.title,
            content: row.content,
            published: row.published,
            view_count: row.view_count,
            created_at: row.post_created_at,
            updated_at: row.post_updated_at,
        };

        let user = User {
            id: row.user_id,
            email: row.email,
            username: row.username,
            password_hash: row.password_hash,
            is_active: row.is_active,
            created_at: row.user_created_at,
            updated_at: row.user_updated_at,
        };

        Ok((post, user))
    }

    pub async fn find_by_user(&self, user_id: i32, published_only: bool) -> Result<Vec<Post>> {
        let posts = if published_only {
            sqlx::query_as!(
                Post,
                "SELECT id, user_id, title, content, published, view_count, created_at, updated_at 
                 FROM posts WHERE user_id = $1 AND published = true ORDER BY created_at DESC",
                user_id
            )
            .fetch_all(&self.pool)
            .await?
        } else {
            sqlx::query_as!(
                Post,
                "SELECT id, user_id, title, content, published, view_count, created_at, updated_at 
                 FROM posts WHERE user_id = $1 ORDER BY created_at DESC",
                user_id
            )
            .fetch_all(&self.pool)
            .await?
        };

        Ok(posts)
    }

    pub async fn increment_view_count(&self, id: i32) -> Result<()> {
        sqlx::query!("UPDATE posts SET view_count = view_count + 1 WHERE id = $1", id)
            .execute(&self.pool)
            .await?;

        Ok(())
    }

    pub async fn search(&self, query: &str, limit: i64) -> Result<Vec<Post>> {
        let search_pattern = format!("%{}%", query);

        let posts = sqlx::query_as!(
            Post,
            "SELECT id, user_id, title, content, published, view_count, created_at, updated_at 
             FROM posts 
             WHERE (title ILIKE $1 OR content ILIKE $1) AND published = true 
             ORDER BY created_at DESC LIMIT $2",
            search_pattern,
            limit
        )
        .fetch_all(&self.pool)
        .await?;

        Ok(posts)
    }
}

// Transaction example
pub struct BlogService {
    pool: PgPool,
}

impl BlogService {
    pub fn new(pool: PgPool) -> Self {
        Self { pool }
    }

    pub async fn create_user_with_first_post(
        &self,
        user_dto: CreateUserDto,
        post_dto: CreatePostDto,
    ) -> Result<(User, Post)> {
        let mut tx = self.pool.begin().await?;

        // Create user
        let user = sqlx::query_as!(
            User,
            r#"
            INSERT INTO users (email, username, password_hash, is_active)
            VALUES ($1, $2, $3, true)
            RETURNING id, email, username, password_hash, is_active, created_at, updated_at
            "#,
            user_dto.email,
            user_dto.username,
            format!("hashed_{}", user_dto.password)
        )
        .fetch_one(&mut *tx)
        .await?;

        // Create post with the new user's ID
        let post = sqlx::query_as!(
            Post,
            r#"
            INSERT INTO posts (user_id, title, content, published, view_count)
            VALUES ($1, $2, $3, $4, 0)
            RETURNING id, user_id, title, content, published, view_count, created_at, updated_at
            "#,
            user.id,
            post_dto.title,
            post_dto.content,
            post_dto.published
        )
        .fetch_one(&mut *tx)
        .await?;

        tx.commit().await?;

        Ok((user, post))
    }
}

// Database initialization
pub async fn create_pool(database_url: &str) -> anyhow::Result<PgPool> {
    let pool = PgPoolOptions::new()
        .max_connections(5)
        .connect(database_url)
        .await?;

    // Run migrations
    sqlx::migrate!("./migrations")
        .run(&pool)
        .await?;

    Ok(pool)
}

use leptos::*;
use serde::{Deserialize, Serialize};
use wasm_bindgen::JsCast;
use web_sys::{Event, SubmitEvent};

#[derive(Clone, Debug, Default, Serialize, Deserialize)]
struct LoginForm {
    email: String,
    password: String,
}

#[derive(Clone, Debug, Default)]
struct FormErrors {
    email: Option<String>,
    password: Option<String>,
    general: Option<String>,
}

#[component]
pub fn LoginComponent() -> impl IntoView {
    let (form_data, set_form_data) = create_signal(LoginForm::default());
    let (errors, set_errors) = create_signal(FormErrors::default());
    let (is_loading, set_is_loading) = create_signal(false);
    let (is_success, set_is_success) = create_signal(false);

    let validate_form = move || -> bool {
        let data = form_data.get();
        let mut new_errors = FormErrors::default();
        let mut is_valid = true;

        // Email validation
        if data.email.is_empty() {
            new_errors.email = Some("Email is required".to_string());
            is_valid = false;
        } else if !data.email.contains('@') {
            new_errors.email = Some("Please enter a valid email".to_string());
            is_valid = false;
        }

        // Password validation
        if data.password.is_empty() {
            new_errors.password = Some("Password is required".to_string());
            is_valid = false;
        } else if data.password.len() < 8 {
            new_errors.password = Some("Password must be at least 8 characters".to_string());
            is_valid = false;
        }

        set_errors.set(new_errors);
        is_valid
    };

    let on_submit = move |ev: SubmitEvent| {
        ev.prevent_default();

        if !validate_form() {
            return;
        }

        set_is_loading.set(true);
        set_errors.update(|e| e.general = None);

        let form_data_clone = form_data.get();

        spawn_local(async move {
            match login_user(form_data_clone).await {
                Ok(_) => {
                    set_is_success.set(true);
                    set_is_loading.set(false);
                }
                Err(e) => {
                    set_errors.update(|errors| {
                        errors.general = Some(format!("Login failed: {}", e));
                    });
                    set_is_loading.set(false);
                }
            }
        });
    };

    view! {
        <div class="login-container">
            <h2>"Login"</h2>

            <Show
                when=move || is_success.get()
                fallback=|| view! { <></> }
            >
                <div class="alert alert-success">
                    "Login successful!"
                </div>
            </Show>

            <Show
                when=move || errors.get().general.is_some()
                fallback=|| view! { <></> }
            >
                <div class="alert alert-danger">
                    {move || errors.get().general.unwrap_or_default()}
                </div>
            </Show>

            <form on:submit=on_submit>
                <div class="form-group">
                    <label for="email">"Email"</label>
                    <input
                        type="email"
                        id="email"
                        class="form-control"
                        class:is-invalid=move || errors.get().email.is_some()
                        prop:value=move || form_data.get().email
                        on:input=move |ev| {
                            set_form_data.update(|data| {
                                data.email = event_target_value(&ev);
                            });
                            set_errors.update(|e| e.email = None);
                        }
                    />
                    <Show
                        when=move || errors.get().email.is_some()
                        fallback=|| view! { <></> }
                    >
                        <div class="invalid-feedback">
                            {move || errors.get().email.unwrap_or_default()}
                        </div>
                    </Show>
                </div>

                <div class="form-group">
                    <label for="password">"Password"</label>
                    <input
                        type="password"
                        id="password"
                        class="form-control"
                        class:is-invalid=move || errors.get().password.is_some()
                        prop:value=move || form_data.get().password
                        on:input=move |ev| {
                            set_form_data.update(|data| {
                                data.password = event_target_value(&ev);
                            });
                            set_errors.update(|e| e.password = None);
                        }
                    />
                    <Show
                        when=move || errors.get().password.is_some()
                        fallback=|| view! { <></> }
                    >
                        <div class="invalid-feedback">
                            {move || errors.get().password.unwrap_or_default()}
                        </div>
                    </Show>
                </div>

                <button
                    type="submit"
                    class="btn btn-primary"
                    disabled=move || is_loading.get()
                >
                    <Show
                        when=move || is_loading.get()
                        fallback=|| view! { "Login" }
                    >
                        <span class="spinner-border spinner-border-sm"></span>
                        " Logging in..."
                    </Show>
                </button>
            </form>
        </div>
    }
}

async fn login_user(form_data: LoginForm) -> Result<(), String> {
    // Simulated API call
    gloo_timers::future::TimeoutFuture::new(1000).await;

