import { getStorage, ref, uploadBytesResumable, deleteObject } from 'firebase/storage';
import { getAuth } from 'firebase/auth';
import crypto from 'crypto';

interface FileValidationOptions {
  maxSizeMB?: number;
  allowedTypes?: string[];
  requireAuth?: boolean;
  scanForMalware?: boolean;
}

interface ValidationResult {
  isValid: boolean;
  error?: string;
}

class SecureStorageService {
  private storage = getStorage();
  private auth = getAuth();

  // File validation
  private validateFile(file: File, options: FileValidationOptions): ValidationResult {
    const {
      maxSizeMB = 10,
      allowedTypes = ['image/jpeg', 'image/png', 'image/gif', 'application/pdf'],
      requireAuth = true,
      scanForMalware = true
    } = options;

    // Check authentication
    if (requireAuth && !this.auth.currentUser) {
      return { isValid: false, error: 'User must be authenticated to upload files' };
    }

    // Check file size
    const maxSizeBytes = maxSizeMB * 1024 * 1024;
    if (file.size > maxSizeBytes) {
      return { isValid: false, error: `File size exceeds ${maxSizeMB}MB limit` };
    }

    // Check file type
    if (!allowedTypes.includes(file.type)) {
      return { isValid: false, error: `File type ${file.type} is not allowed` };
    }

    // Check file extension matches MIME type
    const extension = file.name.split('.').pop()?.toLowerCase();
    const expectedExtensions: { [key: string]: string[] } = {
      'image/jpeg': ['jpg', 'jpeg'],
      'image/png': ['png'],
      'image/gif': ['gif'],
      'application/pdf': ['pdf']
    };

    const validExtensions = expectedExtensions[file.type];
    if (validExtensions && !validExtensions.includes(extension || '')) {
      return { isValid: false, error: 'File extension does not match file type' };
    }

    // Check for suspicious file names
    const suspiciousPatterns = [
      /\.exe$/i,
      /\.dll$/i,
      /\.bat$/i,
      /\.cmd$/i,
      /\.scr$/i,
      /\.vbs$/i,
      /\.js$/i,
      /\.jar$/i,
      /\.zip$/i,
      /\.rar$/i,
      /<script/i,
      /javascript:/i,
      /on\w+=/i
    ];

    for (const pattern of suspiciousPatterns) {
      if (pattern.test(file.name)) {
        return { isValid: false, error: 'Suspicious filename detected' };
      }
    }

    return { isValid: true };
  }

  // Simulate malware scanning (in production, use a real service like VirusTotal API)
  private async scanForMalware(file: File): Promise<boolean> {
    return new Promise((resolve) => {
      // Read first few bytes to check for known malicious signatures
      const reader = new FileReader();
      reader.onloadend = () => {
        const arr = new Uint8Array(reader.result as ArrayBuffer);

        // Check for common malicious file signatures
        const signatures = [
          [0x4D, 0x5A], // EXE files
          [0x7F, 0x45, 0x4C, 0x46], // ELF files
          [0x50, 0x4B, 0x03, 0x04], // ZIP files (could contain malware)
        ];

        for (const signature of signatures) {
          if (arr.length >= signature.length) {
            let match = true;
            for (let i = 0; i < signature.length; i++) {
              if (arr[i] !== signature[i]) {
                match = false;
                break;
              }
            }
            if (match) {
              resolve(false); // Potentially malicious
              return;
            }
          }
        }

        resolve(true); // Appears safe
      };

      // Read first 512 bytes
      reader.readAsArrayBuffer(file.slice(0, 512));
    });
  }

  // Generate secure file path
  private generateSecurePath(userId: string, file: File): string {
    const timestamp = Date.now();
    const randomString = crypto.randomBytes(16).toString('hex');
    const sanitizedFileName = file.name.replace(/[^a-z0-9.-]/gi, '_');
    const extension = sanitizedFileName.split('.').pop();

    // Structure: users/{userId}/uploads/{year}/{month}/{timestamp}_{random}.{ext}
    const date = new Date();
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');

    return `users/${userId}/uploads/${year}/${month}/${timestamp}_${randomString}.${extension}`;
  }

  // Secure upload with validation
  async secureUpload(
    file: File,
    options: FileValidationOptions = {},
    onProgress?: (progress: number) => void
  ): Promise<{ url: string; path: string } | { error: string }> {
    try {
      // Validate file
      const validation = this.validateFile(file, options);
      if (!validation.isValid) {
        return { error: validation.error! };
      }

      // Scan for malware if enabled
      if (options.scanForMalware !== false) {
        const isSafe = await this.scanForMalware(file);
        if (!isSafe) {
          console.error('Malware detected in file:', file.name);
          return { error: 'File failed security scan' };
        }
      }

      const user = this.auth.currentUser;
      if (!user) {
        return { error: 'User not authenticated' };
      }

      // Generate secure path
      const path = this.generateSecurePath(user.uid, file);
      const storageRef = ref(this.storage, path);

      // Create metadata with security context
      const metadata = {
        contentType: file.type,
        customMetadata: {
          uploadedBy: user.uid,
          uploadedAt: new Date().toISOString(),
          originalName: file.name,
          fileSize: String(file.size),
          validated: 'true',
          scanned: options.scanForMalware !== false ? 'true' : 'false'
        },
        // Set cache control for security
        cacheControl: 'private, max-age=3600',
        // Add content disposition to prevent XSS via file uploads
        contentDisposition: 'attachment'
      };

      // Upload with resumable upload for reliability
      const uploadTask = uploadBytesResumable(storageRef, file, metadata);

      return new Promise((resolve, reject) => {
        uploadTask.on(
          'state_changed',
          (snapshot) => {
            const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
            onProgress?.(progress);
          },
          (error) => {
            console.error('Upload error:', error);
            reject({ error: 'Upload failed: ' + error.message });
          },
          async () => {
            try {
              const downloadURL = await getDownloadURL(uploadTask.snapshot.ref);

              // Log successful upload for audit
              console.log('Secure upload completed:', {
                userId: user.uid,
                path,
                timestamp: new Date().toISOString()
              });

              resolve({ url: downloadURL, path });
            } catch (error) {
              reject({ error: 'Failed to get download URL' });
            }
          }
        );
      });
    } catch (error: any) {
      console.error('Secure upload error:', error);
      return { error: error.message || 'Upload failed' };
    }
  }

  // Secure file deletion with ownership check
  async secureDelete(path: string): Promise<boolean> {
    try {
      const user = this.auth.currentUser;
      if (!user) {
        throw new Error('User not authenticated');
      }

      // Verify the file belongs to the current user
      if (!path.startsWith(`users/${user.uid}/`)) {
        throw new Error('Unauthorized: Cannot delete files from other users');
      }

      const storageRef = ref(this.storage, path);
      await deleteObject(storageRef);

      console.log('File securely deleted:', {
        userId: user.uid,
        path,
        timestamp: new Date().toISOString()
      });

      return true;
    } catch (error: any) {
      console.error('Secure delete error:', error);
      return false;
    }
  }
}

export const secureStorage = new SecureStorageService();

import React, { useEffect } from 'react';
import { GetServerSideProps } from 'next';
import Head from 'next/head';
import { Container, Card, Badge, Alert } from 'react-bootstrap';

// Use isomorphic-dompurify for Next.js SSR compatibility (provides DOM implementation in Node.js)
// Requires: isomorphic-dompurify ^2.0.0 (includes DOMPurify 3.2.4+ with CVE-2025-26791 fix)
import DOMPurify from 'isomorphic-dompurify';

import { adminDb } from '../lib/firebase-admin';

interface Post {
  id: string;
  title: string;
  content: string;
  authorName: string;
  createdAt: string;
  tags: string[];
  views: number;
}

interface PostPageProps {
  post: Post | null;
  error?: string;
}

export const getServerSideProps: GetServerSideProps<PostPageProps> = async (context) => {
  const { id } = context.params as { id: string };

  try {
    const docRef = adminDb.collection('posts').doc(id);
    const docSnap = await docRef.get();

    if (!docSnap.exists) {
      return {
        notFound: true
      };
    }

    const postData = docSnap.data();

    // Increment view counter
    await docRef.update({
      views: adminDb.FieldValue.increment(1)
    });

    // Serialize Firestore timestamps for client
    const post: Post = {
      id: docSnap.id,
      title: postData?.title || '',
      content: postData?.content || '',
      authorName: postData?.authorName || 'Anonymous',
      tags: postData?.tags || [],
      views: postData?.views || 0,
      createdAt: postData?.createdAt?.toDate().toISOString() || new Date().toISOString(),
    };

    return {
      props: {
        post
      },
    };
  } catch (error) {
    console.error('Error fetching post:', error);
    return {
      props: {
        post: null,
        error: 'Failed to load post'
      }
    };
  }
};

// Define security hook outside component for stable reference (prevents memory leaks)
const securityHook = (node: any) => {
  if (node.nodeName === 'A') {
    // Enforce noopener noreferrer on external links (prevents reverse tabnapping)
    if (node.getAttribute('target') === '_blank') {
      node.setAttribute('rel', 'noopener noreferrer');
    }
    // Defense-in-depth: Block javascript: protocol (redundant with ALLOWED_URI_REGEXP but safe)
    const href = node.getAttribute('href');
    if (href && href.toLowerCase().startsWith('javascript:')) {
      node.removeAttribute('href');
    }
  }
};

const PostPage: React.FC<PostPageProps> = ({ post, error }) => {
  // Register DOMPurify hook once on component mount with stable reference
  useEffect(() => {
    DOMPurify.addHook('afterSanitizeAttributes', securityHook);

    // Cleanup: Remove hook on component unmount using same reference
    return () => {
      DOMPurify.removeHook('afterSanitizeAttributes', securityHook);
    };
  }, []);

  if (error) {
    return (
      <Container className="mt-5">
        <Alert variant="danger">{error}</Alert>
      </Container>
    );
  }

  if (!post) {
    return null;
  }

  return (
    <>
      <Head>
        <title>{post.title}</title>
        <meta name="description" content={post.content.substring(0, 160)} />
      </Head>

      <Container className="mt-5">
        <Card>
          <Card.Header>
            <h1>{post.title}</h1>
            <div className="d-flex justify-content-between align-items-center">
              <small className="text-muted">
                By {post.authorName} • {new Date(post.createdAt).toLocaleDateString()}
              </small>
              <small className="text-muted">{post.views} views</small>
            </div>
          </Card.Header>
          <Card.Body>
            {/* XSS Prevention: DOMPurify sanitizes user HTML per OWASP A03:2021 (Injection) */}
            <div dangerouslySetInnerHTML={{
              __html: DOMPurify.sanitize(post.content, {
                ALLOWED_TAGS: ['p', 'br', 'strong', 'em', 'u', 'a', 'ul', 'ol', 'li', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6'],
                ALLOWED_ATTR: ['href', 'target', 'rel'],
                // Allow https://, mailto:, absolute paths (/), relative paths (./), and hash links (#)
                ALLOWED_URI_REGEXP: /^(?:(?:https?|mailto):\/\/|\/(?!\/)[\w\-\/]*|\.\/[\w\-\/]+|\#[\w\-]+)$/i,
                KEEP_CONTENT: false,          // Remove disallowed tags entirely
                RETURN_DOM: false,            // Return string, not DOM object
                RETURN_DOM_FRAGMENT: false,   // Return string, not fragment
                RETURN_DOM_IMPORT: false,     // Don't create importable node
                FORCE_BODY: true,             // Wrap in <body> for consistent parsing
                WHOLE_DOCUMENT: false,        // Sanitize fragment, not full document
                SANITIZE_DOM: true            // Enable DOM sanitization
              })
            }} />
          </Card.Body>
          <Card.Footer>
            {post.tags.map((tag) => (
              <Badge key={tag} bg="secondary" className="me-2">
                {tag}
              </Badge>
            ))}
          </Card.Footer>
        </Card>
      </Container>
    </>
  );
};

export default PostPage;

// middleware.ts
import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';
import crypto from 'crypto';

export function middleware(request: NextRequest) {
  const nonce = crypto.randomBytes(16).toString('base64');
  const cspHeader = `
    default-src 'self';
    script-src 'self' 'nonce-${nonce}' 'strict-dynamic' https: 'unsafe-inline' ${
      process.env.NODE_ENV === 'development' ? "'unsafe-eval'" : ''
    };
    style-src 'self' 'unsafe-inline' https://fonts.googleapis.com https://cdn.jsdelivr.net;
    img-src 'self' blob: data: https:;
    font-src 'self' https://fonts.gstatic.com;
    object-src 'none';
    base-uri 'self';
    form-action 'self';
    frame-ancestors 'none';
    block-all-mixed-content;
    upgrade-insecure-requests;
    connect-src 'self' https://identitytoolkit.googleapis.com https://firestore.googleapis.com https://firebase.googleapis.com wss://*.firebaseio.com;
  `.replace(/\s{2,}/g, ' ').trim();

  const requestHeaders = new Headers(request.headers);
  requestHeaders.set('x-nonce', nonce);
  requestHeaders.set('Content-Security-Policy', cspHeader);

  const response = NextResponse.next({
    request: {
      headers: requestHeaders,
    },
  });

  // Add security headers
  response.headers.set('Content-Security-Policy', cspHeader);
  response.headers.set('X-Frame-Options', 'DENY');
  response.headers.set('X-Content-Type-Options', 'nosniff');
  response.headers.set('Referrer-Policy', 'strict-origin-when-cross-origin');
  response.headers.set('X-XSS-Protection', '1; mode=block');
  response.headers.set('Permissions-Policy', 'camera=(), microphone=(), geolocation=()');
  response.headers.set('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');

  return response;
}

