import { GetServerSideProps } from 'next';
import { adminDb } from '../lib/firebase-admin';
import { Container, Card, Badge } from 'react-bootstrap';
import Head from 'next/head';

interface Post {
  id: string;
  title: string;
  content: string;
  authorName: string;
  createdAt: string;
  tags: string[];
  views: number;
}

interface PostPageProps {
  post: Post | null;
  error?: string;
}

export const getServerSideProps: GetServerSideProps<PostPageProps> = async (context) => {
  const { id } = context.params as { id: string };

  try {
    const docRef = adminDb.collection('posts').doc(id);
    const docSnap = await docRef.get();

    if (!docSnap.exists) {
      return {
        notFound: true
      };
    }

    const postData = docSnap.data();

    // Increment view counter
    await docRef.update({
      views: adminDb.FieldValue.increment(1)
    });

    // Serialize Firestore timestamps for client
    const post: Post = {
      id: docSnap.id,
      title: postData?.title || '',
      content: postData?.content || '',
      authorName: postData?.authorName || 'Anonymous',
      tags: postData?.tags || [],
      views: postData?.views || 0,
      createdAt: postData?.createdAt?.toDate().toISOString() || new Date().toISOString(),
    };

    return {
      props: {
        post
      },
    };
  } catch (error) {
    console.error('Error fetching post:', error);
    return {
      props: {
        post: null,
        error: 'Failed to load post'
      }
    };
  }
};

function PostPage({ post, error }: PostPageProps) {
  if (error) {
    return (
      <Container className="py-5">
        <div className="alert alert-danger">{error}</div>
      </Container>
    );
  }

  if (!post) {
    return (
      <Container className="py-5">
        <div>Post not found</div>
      </Container>
    );
  }

  return (
    <>
      <Head>
        <title>{post.title} | My Blog</title>
        <meta name="description" content={post.content.substring(0, 160)} />
      </Head>

      <Container className="py-5">
        <Card>
          <Card.Body>
            <h1>{post.title}</h1>

            <div className="mb-3">
              {post.tags.map((tag) => (
                <Badge key={tag} bg="secondary" className="me-2">
                  {tag}
                </Badge>
              ))}
            </div>

            <div className="text-muted mb-4">
              <small>
                By {post.authorName} •
                {new Date(post.createdAt).toLocaleDateString()} •
                {post.views} views
              </small>
            </div>

            <div className="post-content">
              {post.content}
            </div>
          </Card.Body>
        </Card>
      </Container>
    </>
  );
}

export default PostPage;

