 await new Promise(resolve => setTimeout(resolve, 1000));
 setSubmitSuccess(true);

 setTimeout(() => {
 setFormData({
 firstName: '',
 lastName: '',
 email: '',
 city: '',
 state: '',
 zip: '',
 terms: false
 });
 setValidated(false);
 setSubmitSuccess(false);
 }, 3000);
 } catch (error) {
