// api/errorHandling.ts
interface RetryOptions {
maxRetries?: number;
retryDelay?: number;
retryOn?: number[];
timeout?: number;
}

class APIError extends Error {
constructor(
 message: string,
 public status: number,
 public code?: string
) {
 super(message);
 this.name = 'APIError';
}
}

// Sleep utility for retry delays
function sleep(ms: number): Promise<void> {
return new Promise(resolve => setTimeout(resolve, ms));
}

// Fetch with timeout
async function fetchWithTimeout(
url: string,
options: RequestInit = {},
timeout: number = 10000
): Promise<Response> {
const controller = new AbortController();
const timeoutId = setTimeout(() => controller.abort(), timeout);

try {
 const response = await fetch(url, {
 ...options,
 signal: controller.signal
 });
 clearTimeout(timeoutId);
 return response;
} catch (error: any) {
 clearTimeout(timeoutId);
 if (error.name === 'AbortError') {
 throw new APIError('Request timeout', 408, 'TIMEOUT');
 }
 throw error;
}
}

// Fetch with retry logic
export async function fetchWithRetry<T = any>(
url: string,
options: RequestInit = {},
retryOptions: RetryOptions = {}
): Promise<T> {
const {
 maxRetries = 3,
 retryDelay = 1000,
 retryOn = [408, 429, 500, 502, 503, 504],
 timeout = 10000
} = retryOptions;

let lastError: Error | APIError;
let attempt = 0;

while (attempt <= maxRetries) {
 try {
 const response = await fetchWithTimeout(url, options, timeout);

 // Parse response
 let data: any;
 const contentType = response.headers.get('content-type');

 if (contentType?.includes('application/json')) {
 data = await response.json();
 } else {
 data = await response.text();
 }

 // Handle HTTP errors
 if (!response.ok) {
 const errorMessage = data?.message || response.statusText;
 const error = new APIError(errorMessage, response.status, data?.code);

 // Retry on specific status codes
 if (attempt < maxRetries && retryOn.includes(response.status)) {
 attempt++;
 await sleep(retryDelay * attempt);
 continue;
 }

 throw error;
 }

 return data;

 } catch (error: any) {
 lastError = error;

 // Don't retry on client errors (except timeout)
 if (error.status && error.status >= 400 && error.status < 500 && error.code !== 'TIMEOUT') {
 throw error;
 }

 // Retry on network errors and server errors
 if (attempt < maxRetries) {
 attempt++;
 await sleep(retryDelay * attempt);
 continue;
 }

 throw error;
 }
}

throw lastError!;
}

// User-friendly error handler
export function handleAPIError(error: unknown): string {
if (error instanceof APIError) {
 switch (error.status) {
 case 400:
 return 'Invalid request. Please check your input and try again.';
 case 401:
 return 'You are not authenticated. Please sign in.';
 case 403:
 return 'You do not have permission to perform this action.';
 case 404:
 return 'The requested resource was not found.';
 case 408:
 return 'Request timeout. Please check your connection and try again.';
 case 429:
 return 'Too many requests. Please wait a moment and try again.';
 case 500:
 return 'Server error. Please try again later.';
 case 503:
 return 'Service temporarily unavailable. Please try again later.';
 default:
 return error.message || 'An unexpected error occurred.';
 }
}

if (error instanceof Error) {
 if (error.message.includes('network') || error.message.includes('fetch')) {
 return 'Network error. Please check your internet connection.';
 }
 return error.message;
}

return 'An unexpected error occurred. Please try again.';
}

// React hook for API calls with error handling
import { useState, useCallback } from 'react';

interface UseAPIOptions<T> {
onSuccess?: (data: T) => void;
onError?: (error: string) => void;
retryOptions?: RetryOptions;
}

export function useAPI<T = any>(options: UseAPIOptions<T> = {}) {
const [data, setData] = useState<T | null>(null);
const [error, setError] = useState<string | null>(null);
const [loading, setLoading] = useState(false);

const execute = useCallback(async (url: string, fetchOptions: RequestInit = {}) => {
 setLoading(true);
 setError(null);

 try {
 const result = await fetchWithRetry<T>(url, fetchOptions, options.retryOptions);
 setData(result);
 options.onSuccess?.(result);
 return result;
 } catch (err) {
 const errorMessage = handleAPIError(err);
 setError(errorMessage);
 options.onError?.(errorMessage);
 throw err;
 } finally {
 setLoading(false);
 }
}, [options]);

const reset = useCallback(() => {
 setData(null);
 setError(null);
 setLoading(false);
}, []);

return {
 data,
 error,
 loading,
 execute,
 reset
};
}

// Usage example
function UserListComponent() {
const { data: users, error, loading, execute } = useAPI<User[]>({
 onSuccess: (users) => console.log(`Loaded ${users.length} users`),
 onError: (error) => console.error('Failed to load users:', error),
 retryOptions: {
 maxRetries: 3,
 retryDelay: 1000
 }
});

useEffect(() => {
 execute('/api/users');
}, [execute]);

if (loading) return <div>Loading users...</div>;
if (error) return <div className="error">{error}</div>;
if (!users) return null;

return (
 <ul>
 {users.map(user => (
 <li key={user.id}>{user.name}</li>
 ))}
 </ul>
);
}

import { useState } from 'react';
import { Button, Modal, Form } from 'react-bootstrap';

interface ConfirmationModalProps {
  show: boolean;
  handleClose: () => void;
  title: string;
  children: React.ReactNode;
  onConfirm: () => void | Promise<void>;
  confirmText?: string;
  cancelText?: string;
  confirmVariant?: string;
}

const ConfirmationModal: React.FC<ConfirmationModalProps> = ({
  show,
  handleClose,
  title,
  children,
  onConfirm,
  confirmText = 'Confirm',
  cancelText = 'Cancel',
  confirmVariant = 'primary'
}) => {
  const [isProcessing, setIsProcessing] = useState(false);

  const handleConfirm = async () => {
    setIsProcessing(true);
    try {
      await onConfirm();
      handleClose();
    } catch (error) {
      console.error('Confirmation error:', error);
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <Modal
      show={show}
      onHide={handleClose}
      centered
      backdrop={isProcessing ? 'static' : true}
      keyboard={!isProcessing}
    >
      <Modal.Header closeButton={!isProcessing}>
        <Modal.Title>{title}</Modal.Title>
      </Modal.Header>
      <Modal.Body>{children}</Modal.Body>
      <Modal.Footer>
        <Button
          variant="secondary"
          onClick={handleClose}
          disabled={isProcessing}
        >
          {cancelText}
        </Button>
        <Button
          variant={confirmVariant}
          onClick={handleConfirm}
          disabled={isProcessing}
        >
          {isProcessing ? 'Processing...' : confirmText}
        </Button>
      </Modal.Footer>
    </Modal>
  );
};

export default ConfirmationModal;

