    }));
  };

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    event.stopPropagation();

    const form = event.currentTarget;

    if (form.checkValidity() === false) {
      setValidated(true);
      return;
    }

    setValidated(true);

    try {
      console.log('Submitting:', formData);
      await new Promise(resolve => setTimeout(resolve, 1000));
      setSubmitSuccess(true);

      setTimeout(() => {
        setFormData({
          firstName: '',
          lastName: '',
          email: '',
          city: '',
          state: '',
          zip: '',
          terms: false
        });
        setValidated(false);
        setSubmitSuccess(false);
      }, 3000);
    } catch (error) {
      console.error('Form submission error:', error);
    }
  };

  return (
    <>
      {submitSuccess && (
        <Alert variant="success" dismissible onClose={() => setSubmitSuccess(false)}>
          Form submitted successfully!
        </Alert>
      )}

      <Form noValidate validated={validated} onSubmit={handleSubmit}>
        <Row className="mb-3">
          <Form.Group as={Col} md="4" controlId="validationCustom01">
            <Form.Label>First name</Form.Label>
            <Form.Control
              required
              type="text"
              name="firstName"
              placeholder="First name"
              value={formData.firstName}
              onChange={handleInputChange}
            />
            <Form.Control.Feedback type="valid">
              Looks good!
            </Form.Control.Feedback>
            <Form.Control.Feedback type="invalid">
              Please provide a valid first name.
            </Form.Control.Feedback>
          </Form.Group>

          <Form.Group as={Col} md="4" controlId="validationCustom02">
            <Form.Label>Last name</Form.Label>
            <Form.Control
              required
              type="text"
              name="lastName"
              placeholder="Last name"
              value={formData.lastName}
              onChange={handleInputChange}
            />
            <Form.Control.Feedback type="valid">
              Looks good!
            </Form.Control.Feedback>
            <Form.Control.Feedback type="invalid">
              Please provide a valid last name.
            </Form.Control.Feedback>
          </Form.Group>
        </Row>

        <Form.Group className="mb-3">
          <Form.Check
            required
            type="checkbox"
            name="terms"
            label="Agree to terms and conditions"
            checked={formData.terms}
            onChange={handleInputChange}
            feedback="You must agree before submitting."
            feedbackType="invalid"
          />
        </Form.Group>

        <Button type="submit">Submit form</Button>
      </Form>
    </>
  );
};

export default ValidatedForm;

import { Container, Row, Col, Card, Badge, Button } from 'react-bootstrap';

interface Product {
  id: string;
  name: string;
  description: string;
  price: number;
  imageUrl: string;
  rating: number;
  inStock: boolean;
  category: string;
}

interface ProductGridProps {
  products: Product[];
  onAddToCart?: (product: Product) => void;
}

const ProductGrid: React.FC<ProductGridProps> = ({ products, onAddToCart }) => {
  const formatPrice = (price: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD'
    }).format(price);
  };

  if (products.length === 0) {
    return (
      <Container className="py-5 text-center">
        <h3>No products found</h3>
        <p className="text-muted">Try adjusting your filters or search criteria</p>
      </Container>
    );
  }

  return (
    <Container>
      <Row className="g-4">
        {products.map((product) => (
          <Col key={product.id} xs={12} sm={6} md={4} lg={3}>
            <Card className="h-100 product-card">
              <div className="position-relative">
                <Card.Img
                  variant="top"
                  src={product.imageUrl}
                  alt={product.name}
                  style={{ height: '200px', objectFit: 'cover' }}
                />
                {!product.inStock && (
                  <Badge
                    bg="danger"
                    className="position-absolute top-0 end-0 m-2"
                  >
                    Out of Stock
                  </Badge>
                )}
                <Badge
                  bg="secondary"
                  className="position-absolute top-0 start-0 m-2"
                >
                  {product.category}
                </Badge>
              </div>

              <Card.Body className="d-flex flex-column">
                <Card.Title className="h6">{product.name}</Card.Title>
                <Card.Text className="small text-muted flex-grow-1">
                  {product.description.length > 100
                    ? `${product.description.substring(0, 100)}...`
                    : product.description}
                </Card.Text>

                <div className="d-flex justify-content-between align-items-center mt-3">
                  <span className="h5 mb-0 text-primary">
                    {formatPrice(product.price)}
                  </span>
                  <Button
                    size="sm"
                    variant={product.inStock ? 'primary' : 'secondary'}
                    disabled={!product.inStock}
                    onClick={() => onAddToCart?.(product)}
                  >
                    {product.inStock ? 'Add to Cart' : 'Unavailable'}
                  </Button>
                </div>
              </Card.Body>
            </Card>
          </Col>
        ))}
      </Row>
    </Container>
  );
};

export default ProductGrid;

import { Card, Container, Row, Col, Spinner, Alert, Button, Badge } from 'react-bootstrap';
import useFirestoreCollection from '../hooks/useFirestoreCollection';

interface Item {
  id: string;
  name: string;
  description: string;
  category: string;
  status: 'active' | 'inactive' | 'pending';
  createdAt: any;
  imageUrl?: string;
}

const ItemList = () => {
  const { data: items, loading, error } = useFirestoreCollection<Item>('items', {
    orderByField: 'createdAt',
    orderDirection: 'desc',
    filters: [
      { field: 'status', operator: '!=', value: 'inactive' }
    ]
  });

  const getStatusBadgeVariant = (status: string) => {
    switch (status) {
      case 'active': return 'success';
      case 'inactive': return 'secondary';
      case 'pending': return 'warning';
      default: return 'light';
    }
  };

  if (loading) {
    return (
      <Container className="d-flex justify-content-center py-5">
        <Spinner animation="border" role="status">
          <span className="visually-hidden">Loading...</span>
        </Spinner>
      </Container>
    );
  }

  if (error) {
    return (
      <Container className="py-5">
        <Alert variant="danger">
          Error loading items: {error.message}
        </Alert>
      </Container>
    );
  }

  if (items.length === 0) {
    return (
      <Container className="py-5">
        <Alert variant="info">
          No items found. Create your first item to get started!
        </Alert>
      </Container>
    );
  }

  return (
    <Container className="py-5">
      <h2 className="mb-4">Items ({items.length})</h2>

      <Row className="g-4">
        {items.map(item => (
          <Col key={item.id} xs={12} sm={6} lg={4}>
            <Card className="h-100 shadow-sm">
              {item.imageUrl && (
                <Card.Img
                  variant="top"
                  src={item.imageUrl}
                  style={{ height: '200px', objectFit: 'cover' }}
                />
              )}
              <Card.Body>
                <div className="d-flex justify-content-between align-items-start mb-2">
                  <Card.Title className="h5">{item.name}</Card.Title>
                  <Badge bg={getStatusBadgeVariant(item.status)}>
                    {item.status}
                  </Badge>
                </div>

                <Card.Text className="text-muted">
                  {item.description}
                </Card.Text>

                <div className="d-flex justify-content-between align-items-center">
                  <small className="text-muted">
                    {item.createdAt?.toDate?.()?.toLocaleDateString() || 'N/A'}
                  </small>

                  <div>
                    <Button variant="link" size="sm">View</Button>
                    <Button variant="link" size="sm">Edit</Button>
                    <Button variant="link" size="sm" className="text-danger">Delete</Button>
                  </div>
                </div>
              </Card.Body>
            </Card>
          </Col>
        ))}
      </Row>
    </Container>
  );
};

export default ItemList;

import { useState } from 'react';
import { getFunctions, httpsCallable } from 'firebase/functions';
import { Button, Alert, Spinner, Card, Form } from 'react-bootstrap';

interface ProcessDataRequest {
  input: string;
  options?: {
    format: 'json' | 'csv';
    compress: boolean;
  };
}

interface ProcessDataResponse {
  success: boolean;
  processedData: any;
  processingTime: number;
  message?: string;
}

const CloudFunctionButton = () => {
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<ProcessDataResponse | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [inputData, setInputData] = useState('');

  const callCloudFunction = async () => {
    if (!inputData.trim()) {
      setError('Please enter some data to process');
      return;
    }

    setLoading(true);
    setError(null);
    setResult(null);

    try {
      const functions = getFunctions();
      const processData = httpsCallable<ProcessDataRequest, ProcessDataResponse>(
        functions,
        'processData'
      );

      const response = await processData({
        input: inputData,
        options: {
          format: 'json',
          compress: inputData.length > 1000
        }
      });

      setResult(response.data);
      console.log('Function result:', response.data);

      if (response.data.success) {
        setInputData('');
      }
    } catch (error: any) {
      console.error('Error calling cloud function:', error);
      setError(error.message || 'An unexpected error occurred');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Card>
      <Card.Body>
        <Card.Title>Cloud Function Demo</Card.Title>

        <Form>
          <Form.Group className="mb-3">
            <Form.Label>Input Data</Form.Label>
            <Form.Control
              as="textarea"
              rows={3}
              placeholder="Enter data to process..."
              value={inputData}
              onChange={(e) => setInputData(e.target.value)}
              disabled={loading}
            />
          </Form.Group>

          <Button
            onClick={callCloudFunction}
            disabled={loading || !inputData.trim()}
            variant="primary"
            className="w-100"
          >
            {loading ? (
              <>
                <Spinner size="sm" className="me-2" />
                Processing...
              </>
            ) : (
              'Run Processing Task'
            )}
          </Button>
        </Form>

        {error && (
          <Alert variant="danger" className="mt-3" dismissible onClose={() => setError(null)}>
            {error}
          </Alert>
        )}

        {result && (
          <Alert variant={result.success ? 'success' : 'warning'} className="mt-3">
            <Alert.Heading>
              {result.success ? 'Success!' : 'Processing Complete'}
            </Alert.Heading>
            {result.message && <p>{result.message}</p>}
            <hr />
            <p className="mb-0">
              Processing Time: {result.processingTime}ms
            </p>
          </Alert>
        )}
      </Card.Body>
    </Card>
  );
};

export default CloudFunctionButton;

import { useRouter } from 'next/router';
import { useAuth } from '../hooks/useAuth';
import { Container, Spinner, Alert } from 'react-bootstrap';
import { useEffect, ComponentType, useState } from 'react';

interface WithAuthOptions {
  redirectTo?: string;
  requireEmailVerification?: boolean;
  allowedRoles?: string[];
  LoadingComponent?: ComponentType;
  UnauthorizedComponent?: ComponentType;
}

function withAuth<P extends object>(
  WrappedComponent: ComponentType<P>,
  options: WithAuthOptions = {}
) {
  const {
    redirectTo = '/login',
    requireEmailVerification = false,
    allowedRoles = [],
    LoadingComponent,
    UnauthorizedComponent
  } = options;

  const WithAuthComponent = (props: P) => {
    const router = useRouter();
    const { user, loading } = useAuth();
    const [isAuthorized, setIsAuthorized] = useState(false);

    useEffect(() => {
      const checkAuth = async () => {
        if (loading) return;

        if (!user) {
          const currentPath = router.asPath;
          sessionStorage.setItem('redirectAfterLogin', currentPath);
          router.replace(redirectTo);
          return;
        }

        if (requireEmailVerification && !user.emailVerified) {
          router.replace('/verify-email');
          return;
        }

        if (allowedRoles.length > 0) {
          try {
            const idTokenResult = await user.getIdTokenResult();
            const userRole = idTokenResult.claims.role || 'user';

            if (!allowedRoles.includes(userRole)) {
              setIsAuthorized(false);
              return;
            }
          } catch (error) {
            console.error('Error checking user role:', error);
            setIsAuthorized(false);
            return;
          }
        }

        setIsAuthorized(true);
      };

      checkAuth();
    }, [user, loading, router]);

    if (loading) {
      if (LoadingComponent) {
        return <LoadingComponent />;
      }
      return (
        <Container className="d-flex justify-content-center align-items-center" style={{ minHeight: '100vh' }}>
          <Spinner animation="border" />
        </Container>
      );
    }

    if (!user) {
      return null;
    }

    if (requireEmailVerification && !user.emailVerified) {
      return (
        <Container className="py-5">
          <Alert variant="warning">
            Please verify your email address to access this page.
          </Alert>
        </Container>
      );
    }

    if (allowedRoles.length > 0 && !isAuthorized) {
      if (UnauthorizedComponent) {
        return <UnauthorizedComponent />;
      }
      return (
        <Container className="py-5">
          <Alert variant="danger">
            You don't have permission to access this page.
          </Alert>
        </Container>
      );
    }

    return <WrappedComponent {...props} />;
  };

  WithAuthComponent.displayName = `withAuth(${WrappedComponent.displayName || WrappedComponent.name || 'Component'})`;

  return WithAuthComponent;
}

export default withAuth;
